function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function modal(title,body,footer=''){ $('#modal-root').innerHTML=`<div class="modal-shade"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2><button data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;setTimeout(()=>$('#modal-root textarea, #modal-root input, #modal-root button')?.focus({preventScroll:true}),0);}
function closeModal(){$('#modal-root').innerHTML='';}
const btn=(action,label,style='',attrs='')=>`<button class="button ${style}" data-action="${action}" ${attrs}>${label}</button>`;
const date=s=>new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('zhigao-desk',6);r.onupgradeneeded=()=>{for(const s of ['tasks','items','media','folders','batches','integrations'])if(!r.result.objectStoreNames.contains(s))r.result.createObjectStore(s,{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function dbOp(method,value,name='tasks'){return new Promise((resolve,reject)=>{const tx=db.transaction(name,method==='getAll'?'readonly':'readwrite'),store=tx.objectStore(name),r=value===undefined?store[method]():store[method](value);tx.oncomplete=()=>resolve(r.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
// MCP 写入须确认数据库事务成功；失败不更新内存、不计完成。
function persistAI(records){return new Promise((resolve,reject)=>{
 if(!db)return reject(Error('浏览器数据库不可用，审稿结果未保存。'));
 const tx=db.transaction([...new Set(records.map(([store])=>store))],'readwrite');
 tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||Error('浏览器数据库写入失败。'));tx.onabort=()=>reject(tx.error||Error('浏览器数据库写入已取消。'));
 try{for(const [store,value] of records)tx.objectStore(store).put(value);}catch(e){tx.abort();reject(e);}
});}
function replaceBatch(b){const i=batches.findIndex(x=>x.id===b.id);if(i<0)batches.unshift(b);else batches[i]=b;}
function refreshAIViews(){if(['home','review'].includes(page)&&!typing())render();}
async function saveAgentBatch(b){await persistAI([['batches',b]]);replaceBatch(b);refreshAIViews();}
async function commitAgentReview(t,b){const records=[['tasks',t]];if(b)records.push(['batches',b]);await persistAI(records);const old=tasks.find(x=>x.id===t.id);if(old)Object.assign(old,t);else tasks.unshift(t);if(b)replaceBatch(b);refreshAIViews();}
// 默认保存当前打开的稿件；AI 连接可传入其他稿件。
async function saveTask(doc=task){if(!doc)return;doc.updated=new Date().toISOString();const i=tasks.findIndex(t=>t.id===doc.id);if(i<0)tasks.unshift(doc);else tasks[i]=doc;const it=itemOf(doc);if(it)it.updated=doc.updated;if(db)try{await dbOp('put',doc);if(it)await dbOp('put',it,'items');}catch{toast('存储空间不足，请先导出稿件备份；当前稿件尚未保存到浏览器。');}else toast('当前浏览器不能保存历史，请在关闭页面前导出稿件。');}
async function saveItem(it){it.updated=new Date().toISOString();if(!items.includes(it))items.unshift(it);if(db)try{await dbOp('put',it,'items');}catch{toast('存储空间不足，任务信息尚未保存到浏览器。');}}
const docsOf=it=>tasks.filter(t=>t.itemId===it.id),itemOf=t=>t?items.find(i=>i.id===t.itemId):null;
const itemName=it=>`${it.author||'未填写达人'}${it.title?' · '+it.title:''}`;
function makeItem({projectId,author='',platform='抖音',kind='视频',type='',title='',migrated=false}){const now=new Date().toISOString();return{id:uid(),projectId,author,platform,kind,type,title,created:now,updated:now,publish:{date:'',link:'',status:'待排期'},...(migrated?{migrated:true}:{})};}
function ensureItem(t){let it=itemOf(t);if(!it){it=makeItem({projectId:t.projectId||project().id,author:t.author||'',platform:t.platform||'抖音',kind:t.kind||'视频',title:(t.filename||'').replace(/\.[^.]+$/,''),migrated:true});items.push(it);t.itemId=it.id;}return it;}
// 旧稿件没有内容任务：各自生成一个任务；图文误标为脚本的改回第一个阶段。
async function migrate(){for(const t of tasks){const had=itemOf(t),it=ensureItem(t);let dirty=!had;if(!reviewStagesFor(t.kind||'视频').includes(t.stage)){t.stage=reviewStagesFor(t.kind||'视频')[0];dirty=true;}if(!had){it.created=t.created||it.created;it.updated=t.updated||it.updated;await dbOp('put',it,'items');}if(dirty)await dbOp('put',t);}}
const stageDoc=(it,stage)=>docsOf(it).filter(d=>d.stage===stage).sort((a,b)=>b.updated.localeCompare(a.updated))[0];
function snapshotRules(){task.rules=clone(effectiveRules(project()));task.notes=project().notes;task.ruleDate=project().date;}
function rescan(){task.base=Object.fromEntries(task.cells.map(c=>[c.id,c.current]));task.findings=scan(task.cells.map(c=>({...c,original:c.current})),task.rules,task.platform);task.ai=null;}
function getCell(id){return task.cells.find(c=>c.id===id);}
// PDF 稿件的“版本”由原件页数和意见内容决定；其他稿件由修改后的文字决定。
const NOTED=new Set(['pdf','video']),noted=t=>NOTED.has(t?.fmt);
const fpOf=t=>noted(t)?fingerprint([{id:'src',current:t.fmt==='pdf'?(t.pages||[]).map(p=>p.text).join('\f'):`${t.filename}|${t.size||0}|${t.duration||0}`},...(t.remarks||[]).map(n=>({id:n.id,current:`${n.page??''}|${n.t??''}|${n.cat||''}|${n.quote||''}|${n.text}|${n.status}`}))]):fingerprint(t.cells);
const lockedCell=id=>id?getCell(id)?.note:'';
const lockedMsg=id=>`${getCell(id).address} 含超链接、图片或域，工作台不能安全改写。请在 Word 里手动修改这一处。`;
function updateOne(c,value){c.current=value;task.base[c.id]=value;task.findings=task.findings.filter(f=>f.cellId!==c.id).concat(scan([{...c,original:value}],task.rules,task.platform).filter(f=>f.cellId));if(task.ai)for(const x of task.ai.changes)if(x.id===c.id&&x.status==='pending')x.status='stale';}
const NOTE_KINDS=['修改','删除','核对','提醒'];
function pdfReview(){const t=task,f=flowOf(t),notes=t.remarks||[],open=notes.filter(n=>n.status==='open').length,byPage=p=>notes.filter(n=>n.page===p.n);return`${reviewHead(`${t.pages.length} 页 · ${notes.length} 条意见 · ${open} 条未处理`,btn('export-pdf-notes',icon('down')+' 导出意见单','primary',notes.length?'':'disabled'))}${metaStrip()}${flowPanel()}${fbPanel()}${t.textless?`<div class="callout">没有从这个 PDF 中读到文字，可能是扫描件或图片。可以对照原页面写意见；AI 深审和规则检查用不了。</div>`:''}<div class="pdf-grid"><section class="document"><div class="doc-toolbar"><span>PDF 原件 · 只读</span><span class="legend">工作台不修改 PDF，改稿意见另出意见单</span></div><div id="pdf-pages">${t.pages.map(p=>`<article class="pdf-page" id="pdf-page-${p.n}"><div class="cell-header"><strong>第 ${p.n} 页</strong>${byPage(p).length?`<span class="tag amber">${byPage(p).length} 条意见</span>`:''}<button class="textbtn" data-action="pdf-note" data-pg="${p.n}">${icon('edit')} 在这一页写意见</button></div>${pdfSheet(p)}${p.text?`<details class="pdf-text"><summary>本页文字（可复制原句）</summary><div class="cell-copy">${esc(p.text)}</div></details>`:''}</article>`).join('')}</div><div class="doc-meta">${icon('shield')} 原件保持不变 · 第 ${f.round} 轮</div></section><aside class="findings"><div class="findings-head"><h3>审稿意见 <span class="tag ${open?'amber':''}">${open} 未处理</span></h3>${btn('pdf-note','＋ 新意见','small soft','data-pg="1"')}</div>${notes.length?notes.map(n=>`<section class="finding ${n.status==='done'?'dim':''}"><div class="finding-title">${icon(n.kind==='修改'||n.kind==='删除'?'edit':'alert')}第 ${n.page} 页 · ${esc(n.kind)}</div>${n.quote?`<div class="change">原句：${esc(n.quote)}</div>`:''}<p>${esc(n.text)}</p><div class="finding-actions"><button class="textbtn" data-action="pdf-locate" data-pg="${n.page}">定位 ↗</button><button class="textbtn" data-action="pdf-note-edit" data-id="${esc(n.id)}">编辑</button><button class="textbtn" data-action="pdf-note-del" data-id="${esc(n.id)}">删除</button>${btn('pdf-note-toggle',n.status==='done'?'改回未处理':'标记已处理','small soft',`data-id="${esc(n.id)}"`)}</div></section>`).join(''):`<div class="finding"><p>还没有意见。点页面上方的“在这一页写意见”，可以引用原句并写修改建议。</p></div>`}<div class="history-actions" style="margin-top:18px"><button class="textbtn" data-action="delete-task">${icon('trash')} 删除本阶段稿件</button></div></aside></div>`;}
function pdfNoteModal(n){const t=task,page=n?.page||1,edit=!!n?.id;modal(edit?'编辑意见':'写一条审稿意见',`<div class="form-grid"><div class="field"><label for="note-page">页码</label><select id="note-page" class="input">${t.pages.map(p=>`<option value="${p.n}" ${p.n===page?'selected':''}>第 ${p.n} 页</option>`).join('')}</select></div><div class="field"><label for="note-kind">类型</label><select id="note-kind" class="input">${NOTE_KINDS.map(k=>`<option ${k===(n?.kind||'修改')?'selected':''}>${k}</option>`).join('')}</select></div><div class="field full"><label for="note-quote">原句（可选，从本页文字中复制）</label><input id="note-quote" class="input" value="${esc(n?.quote||'')}" placeholder="例如：年仅20吨"></div><div class="field full"><label for="note-text">修改建议 / 意见</label><textarea id="note-text" placeholder="写明怎么改、为什么改">${esc(n?.text||'')}</textarea></div></div>`,btn('close-modal','取消')+btn('pdf-note-save',edit?'保存':'添加意见','primary',edit?`data-id="${esc(n.id)}"`:''));}
function pdfNotesHtml(t){const notes=t.remarks||[],f=flowOf(t),it=itemOf(t);return`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${esc(exportName(t,'html'))}</title><style>body{max-width:900px;margin:40px auto;font:15px/1.8 system-ui,'Microsoft YaHei',sans-serif;color:#111;padding:20px}h1{font-size:22px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border:1px solid #ccc;padding:8px 10px;text-align:left;vertical-align:top}th{background:#f2f2f2}.q{color:#555}.done{color:#888}</style><body><h1>审稿意见单</h1><p>稿件：${esc(t.filename)}<br>达人：${esc(t.author||'未填写')} · ${esc(t.platform)} · ${esc(t.kind)} · ${esc(t.stage)} · 第 ${f.round} 轮${it?.title?'<br>内容：'+esc(it.title):''}<br>共 ${notes.length} 条意见。PDF 原件未修改。</p><table><thead><tr><th style="width:60px">序号</th><th style="width:70px">页码</th><th style="width:60px">类型</th><th>原句</th><th>修改建议</th><th style="width:70px">状态</th></tr></thead><tbody>${[...notes].sort((a,b)=>a.page-b.page).map((n,i)=>`<tr class="${n.status==='done'?'done':''}"><td>${i+1}</td><td>第 ${n.page} 页</td><td>${esc(n.kind)}</td><td class="q">${esc(n.quote||'—')}</td><td>${esc(n.text)}</td><td>${n.status==='done'?'已处理':'未处理'}</td></tr>`).join('')}</tbody></table></body></html>`;}
// 视频：原文件存放在单独的 media 库，任务记录只存元数据和时间点意见；不剪辑、不改动原视频。
