const vPlayer=()=>$('#v-player');
function videoReview(){const t=task,f=flowOf(t),notes=t.remarks||[],open=notes.filter(n=>n.status==='open').length,shown=[...notes].filter(n=>vFilter==='all'||n.cat===vFilter).sort((a,b)=>a.t-b.t),cnt=c=>notes.filter(n=>n.cat===c).length,dur=t.duration||0,ready=vMedia.id===t.id&&vMedia.url;return`${reviewHead(`视频 · ${fmtTime(dur)} · ${t.width}×${t.height} · ${notes.length} 条意见 · ${open} 条未处理`,btn('export-video-notes',icon('down')+' 导出意见单','primary',notes.length?'':'disabled'))}${metaStrip()}${flowPanel()}${fbPanel()}<div class="pdf-grid"><section class="document"><div class="doc-toolbar"><span>视频原件 · 只读</span><span class="legend">意见带时间点，核对口播、字幕、画面和品牌露出</span></div><div class="video-wrap">${ready?`<video id="v-player" src="${vMedia.url}" controls preload="metadata" playsinline></video>`:vMedia.id===t.id&&vMedia.missing?`<div class="video-missing"><p>这台电脑的浏览器里找不到这个视频原文件（可能被清理或来自交接包）。意见仍然保留。</p>${btn('video-relink','重新选择原视频','small primary')}</div>`:'<div class="video-missing"><p>正在载入视频…</p></div>'}</div><div class="v-bar"><div class="v-track" id="v-track">${notes.map(n=>`<button class="v-mark ${n.status==='done'?'done':''}" style="left:${dur?Math.min(100,n.t/dur*100):0}%" data-action="v-seek" data-t="${n.t}" title="${esc(fmtTime(n.t))} · ${esc(n.cat)}" aria-label="跳到 ${esc(fmtTime(n.t))}"></button>`).join('')}</div><div class="v-tools"><span class="v-now" id="v-now">00:00.0</span>${btn('v-step','-1 秒','small','data-d="-1"')}${btn('v-step','+1 秒','small','data-d="1"')}${btn('v-note','＋ 在当前时间写意见','small primary',ready?'':'disabled')}</div></div><div class="doc-meta">${icon('shield')} 原视频保持不变 · 第 ${f.round} 轮 · ${(t.size/1048576).toFixed(1)} MB</div></section><aside class="findings"><div class="findings-head"><h3>时间点意见 <span class="tag ${open?'amber':''}">${open} 未处理</span></h3></div><div class="v-filters">${[['all',`全部 ${notes.length}`],...V_CATS.map(c=>[c,`${c} ${cnt(c)}`])].map(([k,l])=>`<button class="${vFilter===k?'active':''}" data-action="v-filter" data-k="${esc(k)}">${esc(l)}</button>`).join('')}</div>${shown.length?shown.map(n=>`<section class="finding ${n.status==='done'?'dim':''}"><div class="finding-title"><button class="textbtn v-time" data-action="v-seek" data-t="${n.t}">${esc(fmtTime(n.t))}</button><span class="tag gray">${esc(n.cat)}</span></div>${n.shot?`<img class="v-shot" src="${n.shot}" alt="${esc(fmtTime(n.t))} 画面">`:''}${n.quote?`<div class="change">原话 / 原字幕：${esc(n.quote)}</div>`:''}<p>${esc(n.text)}</p><div class="finding-actions"><button class="textbtn" data-action="v-note-edit" data-id="${esc(n.id)}">编辑</button><button class="textbtn" data-action="v-note-del" data-id="${esc(n.id)}">删除</button>${btn('pdf-note-toggle',n.status==='done'?'改回未处理':'标记已处理','small soft',`data-id="${esc(n.id)}"`)}</div></section>`).join(''):`<div class="finding"><p>${notes.length?'这个分类下还没有意见。':'还没有意见。播放到需要修改的位置，点“在当前时间写意见”，会自动记下时间点和画面。'}</p></div>`}<div class="history-actions" style="margin-top:18px"><button class="textbtn" data-action="delete-task">${icon('trash')} 删除本阶段稿件</button></div></aside></div>`;}
function vNoteModal(n){const edit=!!n?.id;modal(edit?'编辑时间点意见':'写一条时间点意见',`${n?.shot?`<img class="v-shot" src="${n.shot}" alt="画面">`:''}<div class="form-grid"><div class="field"><label for="vn-time">时间点</label><input id="vn-time" class="input" value="${esc(fmtTime(n?.t||0))}" placeholder="例如 01:23.5"></div><div class="field"><label for="vn-cat">分类</label><select id="vn-cat" class="input">${V_CATS.map(c=>`<option ${c===(n?.cat||'口播')?'selected':''}>${c}</option>`).join('')}</select></div><div class="field full"><label for="vn-quote">原话 / 原字幕（可选）</label><input id="vn-quote" class="input" value="${esc(n?.quote||'')}" placeholder="例如：这件外套无异味"></div><div class="field full"><label for="vn-text">修改建议 / 意见</label><textarea id="vn-text" placeholder="写明怎么改、为什么改">${esc(n?.text||'')}</textarea></div></div>`,btn('close-modal','取消')+btn('v-note-save',edit?'保存':'添加意见','primary',edit?`data-id="${esc(n.id)}"`:''));}
function videoNotesHtml(t){const notes=[...(t.remarks||[])].sort((a,b)=>a.t-b.t),f=flowOf(t),it=itemOf(t),c=k=>notes.filter(n=>n.cat===k).length;return`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${esc(exportName(t,'html'))}</title><style>body{max-width:960px;margin:40px auto;font:15px/1.8 system-ui,'Microsoft YaHei',sans-serif;color:#111;padding:20px}h1{font-size:22px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border:1px solid #ccc;padding:8px 10px;text-align:left;vertical-align:top}th{background:#f2f2f2}img{width:160px;border-radius:4px;display:block}.q{color:#555}.done{color:#888}</style><body><h1>视频审稿意见单</h1><p>稿件：${esc(t.filename)}（${esc(fmtTime(t.duration))}）<br>达人：${esc(t.author||'未填写')} · ${esc(t.platform)} · ${esc(t.kind)} · ${esc(t.stage)} · 第 ${f.round} 轮${it?.title?'<br>内容：'+esc(it.title):''}<br>共 ${notes.length} 条意见：${V_CATS.map(k=>`${k} ${c(k)}`).join(' · ')}。原视频未修改。</p><table><thead><tr><th style="width:44px">序号</th><th style="width:80px">时间点</th><th style="width:70px">分类</th><th style="width:176px">画面</th><th>原话 / 原字幕</th><th>修改建议</th><th style="width:64px">状态</th></tr></thead><tbody>${notes.map((n,i)=>`<tr class="${n.status==='done'?'done':''}"><td>${i+1}</td><td>${esc(fmtTime(n.t))}</td><td>${esc(n.cat)}</td><td>${n.shot?`<img src="${n.shot}" alt="${esc(fmtTime(n.t))}">`:'—'}</td><td class="q">${esc(n.quote||'—')}</td><td>${esc(n.text)}</td><td>${n.status==='done'?'已处理':'未处理'}</td></tr>`).join('')}</tbody></table></body></html>`;}
async function loadVideoMedia(t){if(vMedia.id===t.id&&(vMedia.url||vMedia.missing||vMedia.loading))return;if(vMedia.url)URL.revokeObjectURL(vMedia.url);vMedia={id:t.id,url:null,missing:false,loading:true};let blob=null;try{blob=db?(await dbOp('get',t.id,'media'))?.blob:null;}catch{}if(vMedia.id!==t.id)return;vMedia={id:t.id,url:blob?URL.createObjectURL(blob):null,missing:!blob,loading:false};if(task===t&&page==='review')render();}
function mountVideo(){if(task?.fmt!=='video')return;const t=task;loadVideoMedia(t);const v=vPlayer(),now=$('#v-now');if(!v||!now)return;const tick=()=>{now.textContent=fmtTime(v.currentTime);};v.addEventListener('timeupdate',tick);v.addEventListener('seeked',tick);if(vMedia.at!=null){const at=vMedia.at;vMedia.at=null;v.addEventListener('loadedmetadata',()=>{v.currentTime=at;},{once:true});}}
// 页面图片只渲染一次并缓存在内存（只保留当前稿件）；之后重绘直接用缓存，页面不闪、不跳。
let pdfCache={id:null,urls:[],busy:false};
const pdfSheet=p=>{const url=pdfCache.id===task.id?pdfCache.urls[p.n-1]:null;return`<div class="pdf-sheet" data-page="${p.n}" style="aspect-ratio:${p.w||595} / ${p.h||842}">${url?`<img src="${url}" alt="第 ${p.n} 页原件">`:''}</div>`;};
function mountPdf(){const holder=$('#pdf-pages');if(!holder||task?.fmt!=='pdf'||!task.buffer)return;const t=task;if(pdfCache.id!==t.id)pdfCache={id:t.id,urls:[],busy:false};if(pdfCache.busy||pdfCache.urls.length>=t.pages.length)return;const cache=pdfCache;cache.busy=true;cache.urls=[];const w=Math.max(320,Math.min(900,holder.clientWidth-48));renderPdfImages(t.buffer,w,(n,url)=>{if(pdfCache!==cache)return;cache.urls[n-1]=url;const sheet=document.querySelector(`#pdf-pages .pdf-sheet[data-page="${n}"]`);if(sheet&&task===t&&!sheet.querySelector('img'))sheet.innerHTML=`<img src="${url}" alt="第 ${n} 页原件">`;}).catch(()=>{if(pdfCache===cache&&task===t&&$('#pdf-pages'))toast('PDF 页面渲染失败，文字和意见仍可正常使用。');}).finally(()=>{cache.busy=false;});}
function projectOptions(selected=settings.selected){return settings.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(pname(p))}</option>`).join('');}
function shell(content){const count=tasks.filter(t=>t.findings?.some(f=>f.status==='pending')).length;$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brandmark">${icon('doc')}</div><div class="brand-text"><div class="brand-name">知稿</div><div class="brand-sub">REVIEW STUDIO</div></div></div><div class="navlabel">工作空间</div><nav aria-label="主导航">${[['home','grid','审稿工作台'],['history','history','内容任务'],['rules','doc','品牌资料与口径'],['feishu','sheet','飞书同步']].map(([p,i,t])=>`<button class="navbtn ${page===p||(p==='history'&&(page==='review'||page==='item'))?'active':''}" data-page="${p}" title="${t}">${icon(i)}<span>${t}</span>${p==='history'?`<span class="count">${items.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="navbtn" data-action="help" title="使用指南">${icon('help')}<span>使用指南</span></button><div class="local-note">${icon('shield')} ${folders.has(project().id)&&folderStates.get(project().id)==='granted'?`文件归档到本地：${esc(folders.get(project().id).name)}`:'记录留在本机浏览器'}<br></div><div class="profile"><div class="avatar">L</div><div class="profile-copy">Lychee<small>个人审稿空间</small></div></div></div></aside><main class="workspace"><header class="topbar"><div class="crumb">工作空间 <span>/</span><strong>${({home:'审稿工作台',history:'内容任务',item:'任务详情',feishu:'飞书同步',brand:'品牌资料与口径',rules:'品牌资料与口径',review:'稿件审校'})[page]}</strong></div><div class="top-tools">${agentChip()}<button data-action="help" aria-label="帮助">${icon('help')}</button></div></header><div class="content ${page==='review'?'review-layout-wide':''}">${content}</div></main><input class="hidden" id="file-input" type="file" accept=".xlsx,.docx,.pdf,.txt,.md,.mp4,.mov,.m4v,.webm"><input class="hidden" id="next-input" type="file" accept=".xlsx,.docx,.pdf,.txt,.md,.mp4,.mov,.m4v,.webm"><input class="hidden" id="notes-input" type="file" accept=".md,.txt" multiple><input class="hidden" id="bundle-input" type="file" accept=".zip,.json"><input class="hidden" id="lib-input" type="file" accept=".txt,.md,.docx,.pdf">`;}
// 本机 AI 连接：顶栏状态 + 设置弹窗。连接器把网页接给本机的 Codex、Claude Code、WorkBuddy 等。
const AGENT_TEXT={off:['未连接 AI',''],connecting:['正在连接…','amber'],offline:['连接器未运行','red'],waiting:['已连接 · 等待 AI 客户端','amber'],online:['','on'],'other-tab':['已在其他标签页连接','']};
const CONNECTOR_URL=new URL('./zhigao-connector.mjs',location.href).href;
const agentInstallCmd=()=>`$f="$env:USERPROFILE\\zhigao-connector.mjs"; irm "${CONNECTOR_URL}" -OutFile $f; node $f install`;
function agentChip(){const [t,tone]=AGENT_TEXT[agent.state]||AGENT_TEXT.off,label=agent.state==='online'?`AI 已连接 · ${esc(agent.clients.join('、'))}`:t;return`<button class="agent-chip ${tone}" id="agent-chip" data-action="agent" aria-label="AI 连接：${esc(label)}"><i class="status-dot"></i>${label}</button>`;}
function agentBody(){const s=agent.state;const status=s==='online'?`已连接：${esc(agent.clients.join('、'))}`:s==='waiting'?'连接器已运行，但还没有 AI 客户端接入。请启动已安装连接器的 AI 客户端。':s==='offline'?'没有找到本机连接器。请按下面的步骤安装，安装后启动任一 AI 客户端即可（连接器由 AI 客户端自动拉起）。':s==='other-tab'?'这个浏览器的另一个工作台标签页已经连接了 AI。关闭那个标签页后，这里会自动接上。':s==='connecting'?'正在连接本机连接器…':'连接后，在 AI 客户端发起审稿或提炼。';
 const log=agent.log.length?`<div class="agent-log">${agent.log.slice(0,12).map(l=>`<div class="${l.ok?'':'bad'}"><span>${date(l.at)}</span><strong>${esc(l.client||'AI')}</strong>${esc(l.label)}${l.path?` · ${esc(l.path)}`:''}${l.ok?'':` · ${esc(l.error)}`}</div>`).join('')}</div>`:'<p class="muted">还没有 AI 调用记录。</p>';
 return`<div class="callout"><strong>状态</strong>：${status}</div>
<h3>首次使用：安装连接器（每台电脑一次）</h3>
<ol class="steps-list"><li>安装 <a href="https://nodejs.org/zh-cn" target="_blank" rel="noopener">Node.js</a> 18 或更新版本（已装可跳过）。</li><li>打开 PowerShell，粘贴下面这行并回车。它会下载连接器，并自动接入本机检测到的 Claude Code、Codex、WorkBuddy、DeepSeek Harness。<textarea id="agent-cmd" readonly style="min-height:64px;margin-top:8px">${esc(agentInstallCmd())}</textarea>${btn('agent-copy','复制命令','small')} <a class="button small" href="./zhigao-connector.mjs" download="zhigao-connector.mjs">下载连接器文件</a></li><li>重启 AI 客户端，然后点下方“连接”。浏览器若询问是否允许访问本机网络，选“允许”。</li><li>对 AI 说：“用知稿审一下待处理的稿件”。</li></ol>
<p class="muted">豆包、DeepSeek、GLM 等模型：在任一支持 MCP 的客户端（如 Claude Code、Codex、DeepSeek Harness、Cherry Studio、Trae）里选用这个模型即可。其他客户端手动添加 stdio 服务：命令 <code>node</code>，参数为连接器文件路径。Mac 把命令换成 <code>curl -o ~/zhigao-connector.mjs ${esc(CONNECTOR_URL)} && node ~/zhigao-connector.mjs install</code>。</p>

<h3>最近的 AI 调用</h3>${log}`;}
function agentModal(){modal('AI 连接',`<div id="agent-body">${agentBody()}</div>`,btn('close-modal','关闭')+(agent.state==='off'?btn('agent-on','连接','primary'):btn('agent-off','断开')));}
function agentChanged(){const c=$('#agent-chip');if(c)c.outerHTML=agentChip();const b=$('#agent-body');if(b){const sel=getSelection();if(!(sel&&!sel.isCollapsed&&b.contains(sel.anchorNode)))b.innerHTML=agentBody();}const f=$('#modal-root .modal-footer [data-action=agent-on], #modal-root .modal-footer [data-action=agent-off]');if(f&&b)f.outerHTML=agent.state==='off'?btn('agent-on','连接','primary'):btn('agent-off','断开');}
function render(){if(page==='brand')page='rules';if(page==='review'&&!task)page='home';if(page==='item'&&!items.includes(item))page='history';shell(page==='home'?home():page==='rules'?rulesPage():page==='history'?historyPage():page==='feishu'?feishuPage():page==='brand'?brandPage():page==='item'?itemPage():task.fmt==='pdf'?pdfReview():task.fmt==='video'?videoReview():review());bindDrop();if(page==='review'){mountPdf();mountVideo();}}
function steps(pr,it,big=false){const last=pr.stages.reduce((n,s,k)=>s.doc?k:n,-1),ps=it.publish?.status||'待排期';return`<div class="steps-mini ${big?'big':''}">${pr.stages.map((s,k)=>{const cls=s.state==='passed'?'done':pr.current===s.name||s.doc?'now':k<last?'skip':'todo',tip=s.doc?FLOW_STATES[s.state].label:k<last?'未记录':'未开始';return`<span class="step ${cls}" title="${esc(s.name)}：${esc(tip)}">${esc(s.name)}</span>`;}).join('')}<span class="step ${ps==='已发布'?'done':pr.current==='发布'?'now':'todo'}" title="发布：${esc(ps)}">发布</span></div>`;}
function itemTable(list){if(!list.length&&page==='history'&&(search.trim()||Object.values(listFilter).some(Boolean)))return`<div class="empty">${icon('doc')}<p>没有符合条件的任务</p><small>换个筛选条件，或清除筛选。</small></div>`;if(!list.length)return`<div class="empty">${icon('doc')}<p>还没有内容任务</p><small>新建一个“达人＋平台＋一篇内容”的任务，或直接上传来稿。</small></div>`;return`<table class="task-table item-table"><thead><tr><th>达人 / 内容</th><th>阶段进度</th><th>当前状态</th><th>排期 / 发布</th><th>最近更新</th><th style="width:96px">操作</th></tr></thead><tbody>${list.map(it=>{const pr=itemProgress(it,docsOf(it)),pend=pr.doc?reviewStatus(pr.doc):null;return`<tr><td><div class="task-file"><div class="fileicon">${icon('doc')}</div><div><strong>${esc(itemName(it))}</strong><small>${esc(it.platform)} · ${esc(it.kind)}${it.type?' · '+esc(it.type):''} · ${esc(pnameById(it.projectId))}</small></div></div></td><td>${steps(pr,it)}</td><td><span class="tag ${pr.tone}">${esc(pr.current)} · ${esc(pr.label)}</span>${pend?.tone?`<small class="pending-note">${esc(pend.label)}</small>`:''}</td><td>${esc(it.publish?.date||'未排期')}<small class="muted" style="display:block;margin-top:6px">${esc(it.publish?.status||'待排期')}</small>${(()=>{const n=daysToPublish(it);return n!=null&&n<=3?`<small class="pending-note" style="color:${n<0?'#b03a3a':'#8a6d3b'}">${esc(dueLabel(n))}</small>`:'';})()}</td><td class="muted">${date(it.updated)}</td><td><button class="textbtn" data-action="open-item" data-id="${esc(it.id)}">打开 →</button></td></tr>`;}).join('')}</tbody></table>`;}
let listFilter={wait:'',platform:'',kind:'',type:'',stage:'',due:''};
function listItems(){const q=search.trim().toLowerCase(),scope=listProject==='all'?items:items.filter(i=>i.projectId===project().id),f=listFilter;return scope.filter(i=>(!q||[itemName(i),i.platform,i.kind,i.type||'',pnameById(i.projectId)].join(' ').toLowerCase().includes(q))&&matchFilter(i,itemProgress(i,docsOf(i)),f)).sort((a,b)=>b.updated.localeCompare(a.updated));}
