function publishCard(it,pr){const pb=it.publish||{},st=pb.status||'待排期';return`<section class="panel"><div class="panel-heading"><h2>发布</h2><span class="tag ${PUBLISH_TONE[st]||'amber'}">${esc(st)}</span></div><div class="stage-body form-grid"><div class="field"><label for="pub-date">排期日期</label><input id="pub-date" type="date" class="input" value="${esc(pb.date||'')}"></div><div class="field"><label for="pub-status">发布状态</label><select id="pub-status" class="input">${PUBLISH_STATES.map(s=>`<option ${s===st?'selected':''}>${s}</option>`).join('')}</select></div><div class="field full"><label for="pub-link">发布链接</label><input id="pub-link" class="input" value="${esc(pb.link||'')}" placeholder="https://"></div><p class="muted full">${pr.current==='发布'?'内容阶段已全部通过品牌审核。':'内容阶段尚未全部通过品牌审核；排期可以先填。'}</p><div class="full">${btn('save-publish','保存发布信息','small primary')}</div></div></section>`;}
