const FS_LINKS=[['source','原始资料表','品牌方或同事维护的原始表，用来提取达人和任务。'],['refined','精炼审核表','日常跟进用的精炼表，同步进度以它为准。']];
let fsDraft=null,fsEmbed=null,fsLastMade=null,fsLive=null,fsPendingWrites=null;
const fsOf=p=>p.feishu||(p.feishu={source:null,refined:null,sheets:[]});
const fsAge=at=>{const h=(Date.now()-new Date(at))/36e5;return h<1?`${Math.max(1,Math.round(h*60))} 分钟前`:h<48?`${Math.round(h)} 小时前`:`${Math.round(h/24)} 天前`;};
const fsTone=s=>s==='update'?'dark':s==='conflict'?'amber':'gray',fsWord=s=>s==='update'?'待写入':s==='conflict'?'待处理':'一致';
function fsLinkCard(p,[k,label,desc]){const L=fsOf(p)[k],emb=fsEmbed?.pid===p.id&&fsEmbed.k===k;return`<section class="panel"><div class="panel-heading"><h2>${esc(label)}</h2><span class="tag ${L?'dark':'gray'}">${L?'已填写链接':'未填写'}</span></div><div class="stage-body"><p class="muted" style="margin:0 0 12px">${esc(desc)}</p><div class="fs-url"><input class="input" id="fs-url-${k}" value="${esc(L?.url||'')}" placeholder="https://xxx.feishu.cn/wiki/…?sheet=…" aria-label="${esc(label)}链接">${btn('fs-save-link','保存','small',`data-k="${k}"`)}</div>${L?`<div class="toolbar-actions" style="margin-top:12px"><a class="button small" href="${esc(L.url)}" target="_blank" rel="noopener noreferrer">在飞书中打开 ↗</a>${btn('fs-embed',emb?'收起':'在工作台内显示','small',`data-k="${k}"`)}</div>`:''}</div></section>`;}
function fsEmbedPanel(p){const L=fsEmbed?.pid===p.id&&fsOf(p)[fsEmbed.k];if(!L)return'';return`<section class="panel fs-embed"><div class="panel-heading"><h2>${esc(FS_LINKS.find(x=>x[0]===fsEmbed.k)[1])} · 嵌入显示</h2>${btn('fs-embed','收起','small',`data-k="${fsEmbed.k}"`)}</div><div class="stage-body"><p class="muted" style="margin:0 0 10px">如果下面一直空白、提示拒绝连接或要求登录，说明飞书不允许在这里嵌入，或这台电脑的浏览器还没登录飞书，请点“在飞书中打开”。表格有更新时点击“刷新表格”。</p><iframe class="fs-frame" src="${esc(L.url)}" title="飞书页面" referrerpolicy="strict-origin-when-cross-origin"></iframe></div></section>`;}
function fsLiveCard(p,sheets,meta,issue){const F=fsOf(p),L=F.refined,ready=sheets.length>0;return`<section class="panel"><div class="panel-heading"><h2>飞书连接</h2><span class="tag ${ready?'dark':issue?'red':'gray'}">${ready?`已读取 · ${esc(meta?.identity?.userName||'飞书用户')}`:issue?'连接失败':'按需连接'}</span></div><div class="stage-body"><p class="muted">保存精炼表链接后，点击读取；表格有更新时可随时刷新。</p><div class="toolbar-actions" style="margin-top:12px">${btn('fs-live-read-all',ready?'刷新表格':'读取全部子表','small primary',L?'':'disabled')}</div>${issue?`<p class="error" style="margin-top:10px">${esc(issue)}</p>`:''}${ready?`<p class="muted" style="margin-top:12px">${esc(meta?.title||'精炼审核表')} · ${sheets.length} 个可见子表 · ${esc(fsAge(meta?.at||new Date().toISOString()))}</p><div class="file-list" style="margin-top:10px">${sheets.map(s=>`<div class="file-chip">${esc(s.name)} · ${s.rows.length} 行 · ${s.headers.length} 列</div>`).join('')}</div>`:''}${meta?.lastWrite?`<div class="callout" style="margin-top:12px">上次同步：成功 ${meta.lastWrite.written} 格，未完成 ${meta.lastWrite.rejected} 格。${meta.lastWrite.rejected?` ${meta.lastWrite.results.filter(x=>x.status!=='written').map(x=>`${x.cell||x.field}：${x.error}`).join('；')}`:''}</div>`:''}</div></section>`;}
const fsExtractCard=()=>`<section class="panel"><div class="panel-heading"><h2>从原始表提取任务</h2>${btn('fs-paste','粘贴原始表','small','data-mode="raw"')}</div><div class="stage-body"><p class="muted" style="margin:0">复制原始表并粘贴，按达人、平台和档期批量建立内容任务。</p></div></section>`;
function fsSheetsCard(p){const S=fsOf(p).sheets;return`<section class="panel"><div class="panel-heading"><h2>已读取的子表</h2>${btn('fs-paste','＋ 粘贴一个子表','small primary','data-mode="sheet"')}</div><div class="stage-body"><p class="muted" style="margin:0 0 12px">也可以从飞书复制子表（含表头），粘贴到这里。</p>${S.length?`<table class="task-table fs-table"><thead><tr><th>子表</th><th style="width:70px">行数</th><th>已对应字段</th><th style="width:130px">更新时间</th><th style="width:230px">操作</th></tr></thead><tbody>${S.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${s.rows.length}</td><td class="muted">${esc(FIELDS.filter(f=>s.map[f.k]>=0).map(f=>f.label).join('、'))}</td><td>${esc(fsAge(s.at))}${Date.now()-new Date(s.at)>2*36e5?'<br><span class="tag amber" style="margin-top:4px">可能已过时</span>':''}</td><td><button class="textbtn" data-action="fs-paste" data-mode="sheet" data-sid="${esc(s.id)}">更新数据</button><button class="textbtn" data-action="fs-map" data-sid="${esc(s.id)}">字段对应</button><button class="textbtn" data-action="fs-del-sheet" data-sid="${esc(s.id)}">删除</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty" style="padding:18px">还没有读取表格。</div>'}</div></section>`;}
function fsLiveSheets(p){const L=fsOf(p).refined;return L?fsOf(p).sheets.filter(s=>s.live&&s.sourceUrl===L.url):[];}
function fsLiveWrites(p){const S=fsLiveSheets(p),plan=buildPlan(items.filter(i=>i.projectId===p.id&&i.feishu),docsOf,S);return plan.flatMap(e=>(e.cells||[]).filter(c=>c.status==='update').map(c=>({e,c}))).filter(({e,c})=>['author','platform'].every(f=>e.sheet.map?.[f]>=0)&&e.sheet.remoteId&&typeof c.ours==='string'&&c.ours.trim());}
function fsWritePayload(p){const groups=new Map();for(const {e,c} of fsLiveWrites(p)){const sheet=e.sheet,group=groups.get(sheet.remoteId)||{sheetId:sheet.remoteId,writes:[]},r=sheet.rows[e.row],m=sheet.map;group.writes.push({status:c.status,field:c.f,header:c.header,column:m[c.f],value:c.ours,...(c.expected!==undefined?{expected:c.expected}:{}),key:{author:cellOf(r,m,'author'),platform:cellOf(r,m,'platform'),title:cellOf(r,m,'title')},keyColumns:{author:m.author,platform:m.platform,title:m.title}});groups.set(sheet.remoteId,group);}return[...groups.values()];}
function fsConfirmWriteModal(p){const groups=fsWritePayload(p),flat=groups.flatMap(g=>g.writes.map(w=>({g,w}))),n=flat.length;if(!n)return toast('没有可写入的差异。');if(n>20)return toast(`这次有 ${n} 个空白格，单批最多 20 个；请缩小范围后再同步。`);fsPendingWrites={pid:p.id,url:fsOf(p).refined?.url,groups};modal(`确认写入飞书 · ${n} 个单元格`,`<p>本次将更新以下内容。</p><div class="fs-list"><table class="task-table"><thead><tr><th>子表 / 任务</th><th>字段</th><th>原值 → 写入内容</th></tr></thead><tbody>${flat.map(({g,w})=>{const x=items.find(i=>i.projectId===p.id&&i.feishu&&fsOf(p).sheets.find(s=>s.id===i.feishu.sheetId)?.remoteId===g.sheetId&&normName(i.author)===normName(w.key.author)&&normName(i.title)===normName(w.key.title));return`<tr><td>${esc(x?itemName(x):`${w.key.author} · ${w.key.title}`)}<small class="muted" style="display:block">${esc(p.feishu.sheets.find(s=>s.remoteId===g.sheetId)?.name||'')}</small></td><td>${esc(w.header)}</td><td><div class="fs-val">${w.expected!==undefined?esc(w.expected)+' → ':''}${esc(w.value)}</div></td></tr>`;}).join('')}</tbody></table></div>`,btn('close-modal','取消')+btn('fs-write-confirm',`确认并写入 ${n} 格`,'primary'));}
async function fsReadAllIntoProject(p,data){const F=fsOf(p),L=F.refined,url=L?.url;if(!url)throw Error('请先保存精炼审核表链接。');if(!Array.isArray(data.sheets)||!data.sheets.length)throw Error('飞书没有返回可读取的子表。');const before=[...F.sheets],created=[];for(const raw of data.sheets){const old=before.find(s=>s.liveId===raw.sheetId&&s.sourceUrl===url)||before.find(s=>!s.sourceUrl&&s.name===raw.name),map=autoMap(raw.headers);if(old)for(const [f,i] of Object.entries(old.map||{})){if(i<0)continue;const h=old.headers?.[i],n=raw.headers.findIndex(x=>x===h);if(n>=0)map[f]=n;}created.push({...(old||{}),id:old?.id||uid(),remoteId:raw.sheetId,liveId:raw.sheetId,live:true,stale:false,sourceUrl:url,name:raw.name,headers:raw.headers,rows:raw.rows,writeHistory:raw.writeHistory||[],map,at:new Date().toISOString(),revision:data.revision,range:raw.range,rowStart:raw.rowStart});}for(const old of F.sheets)if(old.live&&(old.sourceUrl!==url||!created.some(s=>s.liveId===old.liveId))){old.live=false;old.stale=true;}for(const sheet of created){const i=F.sheets.findIndex(s=>s.id===sheet.id);if(i>=0)F.sheets[i]=sheet;else F.sheets.push(sheet);}let rebound=0;for(const it of items.filter(i=>i.projectId===p.id&&i.feishu)){const old=before.find(s=>s.id===it.feishu.sheetId);if(!old)continue;const key=it.feishu.key,hits=created.flatMap(s=>s.rows.map((_,row)=>({s,row})).filter(x=>rowKey(x.s,x.row)===key));if(hits.length===1&&it.feishu.sheetId!==hits[0].s.id){bindTo(it,hits[0].s,hits[0].row);await saveItem(it);rebound++;}}F.liveMeta={...F.liveMeta,url,title:data.title,revision:data.revision,identity:data.identity,at:new Date().toISOString()};saveSettings();return{count:created.length,rebound,oldCount:before.filter(s=>!s.live).length};}
function fsSyncCard(p){const list=items.filter(i=>i.projectId===p.id),S=fsOf(p).sheets,bound=list.filter(i=>i.feishu),allPlan=buildPlan(bound,docsOf,S),plan=allPlan.filter(e=>e.sheet?.live&&e.sheet.sourceUrl===fsOf(p).refined?.url),cells=plan.flatMap(e=>(e.cells||[]).map(c=>({e,c}))).filter(x=>x.c.status!=='skip'),n=s=>cells.filter(x=>x.c.status===s).length,errs=allPlan.filter(e=>e.error),stale=bound.filter(i=>{const s=S.find(x=>x.id===i.feishu.sheetId);return !s?.live||s.sourceUrl!==fsOf(p).refined?.url;}),unbound=list.filter(i=>!i.feishu),writes=fsLiveWrites(p);return`<section class="panel" id="fs-sync"><div class="panel-heading"><h2>同步进度</h2><div class="toolbar-actions">${btn('fs-autobind','自动关联','small',S.length&&unbound.length?'':'disabled')}${btn('fs-copy-plan','复制待更新清单','small',n('update')||n('conflict')||errs.length?'':'disabled')}${btn('fs-live-prepare-write',writes.length<=20&&writes.length?`确认写入 ${writes.length} 格`:'同步到飞书','small primary',writes.length>20||!writes.length?'disabled':'')}</div></div><div class="stage-body"><div class="fs-summary"><span>已关联 ${bound.length} / ${list.length} 个任务</span><span class="tag dark">待同步 ${n('update')}</span><span class="tag amber">待处理 ${n('conflict')+errs.length+stale.length}</span><span class="tag gray">一致 ${n('same')}</span></div>${writes.length>20?'<p class="error">一次最多确认写入 20 个空白格，请缩小待处理范围后再试。</p>':''}${stale.length?`<p class="callout">${stale.length} 个已关联任务仍指向旧快照或尚未读取的子表。请读取精炼审核表全部子表，再按达人、平台和标题重新关联。</p>`:''}${cells.length||errs.length?`<table class="task-table fs-table"><thead><tr><th>任务</th><th>子表</th><th style="width:90px">字段</th><th>飞书当前</th><th>工作台</th><th style="width:150px">结果</th></tr></thead><tbody>${errs.map(e=>`<tr><td>${esc(itemName(e.it))}<small class="muted" style="display:block">${esc(e.it.platform)}</small></td><td colspan="4"><span class="error">${esc(e.error)}</span></td><td>${btn('fs-bind','重新关联','small',`data-id="${esc(e.it.id)}"`)}</td></tr>`).join('')}${cells.map(({e,c})=>`<tr><td>${esc(itemName(e.it))}<small class="muted" style="display:block">${esc(e.it.platform)}</small></td><td>${esc(e.sheet.name)}</td><td>${esc(c.header)}</td><td><div class="fs-val">${esc(c.feishu||'（空）')}</div></td><td><div class="fs-val">${esc(c.ours||'（空）')}</div></td><td><span class="tag ${fsTone(c.status)}">${fsWord(c.status)}</span>${c.note?`<small class="muted" style="display:block;margin-top:4px">${esc(c.note)}</small>`:''}</td></tr>`).join('')}</tbody></table>`:bound.length?'<p class="muted">已关联的任务和最新在线表格之间没有需要处理的差异。</p>':''}${unbound.length?`<div class="fs-unbound"><strong>未关联的任务 · ${unbound.length}</strong>${unbound.map(i=>`<div><span>${esc(itemName(i))} · ${esc(i.platform)} · ${esc(i.kind)}</span>${btn('fs-bind','关联','small',`data-id="${esc(i.id)}"`+(S.length?'':' disabled'))}</div>`).join('')}</div>`:''}</div></section>`;}
function feishuPage(){const p=project(),F=fsOf(p),L=F.refined,live=fsLiveSheets(p),meta=fsLive?.url===L?.url?fsLive:F.liveMeta?.url===L?.url?F.liveMeta:null,issue=meta?.error||meta?.lastWriteError;return`<div class="page-title"><div><h1>飞书同步</h1><p>${esc(pname(p))} · 用原始表提取任务，用精炼表核对进度。</p></div><span class="tag ${live.length?'dark':'amber'} fs-api">${live.length?'已读取':'尚未读取'}</span></div><div class="banner">粘贴原始表链接，在 AI 客户端说“提炼”。生成的精炼表会显示在这里，上传稿件后按达人昵称关联。</div><div class="fs-page"><div class="fs-grid">${FS_LINKS.map(x=>fsLinkCard(p,x)).join('')}</div>${fsLiveCard(p,live,meta,issue)}${refinedPreview(p)}${fsEmbedPanel(p)}${extractionCard(p)}${fsExtractCard()}${fsSheetsCard(p)}${fsSyncCard(p)}</div>`;}
// 精炼表里的“达人类型”（方向）。旧快照的字段对应里没有这一项时，按表头现场识别。
const fsTypeIdx=s=>s.map&&'type' in s.map?s.map.type:autoMap(s.headers).type;
const fsTypeOf=(s,row)=>{const i=fsTypeIdx(s);return i>=0?String(s.rows[row]?.[i]??'').trim():'';};
// 只补工作台里还空着的达人类型和档期，已有的不覆盖；标题不补，免得本地文件夹名变化。
function fsFillable(it,e){const out=[],ty=fsTypeOf(e.sheet,e.row),d=dateISO(cellOf(e.sheet.rows[e.row],e.sheet.map,'date'));if(ty&&!it.type)out.push(['type',ty,'达人类型']);if(d&&!it.publish?.date)out.push(['date',d,'发布档期']);return out;}
function feishuCard(it){const p=settings.projects.find(x=>x.id===it.projectId)||project(),S=fsOf(p).sheets,b=it.feishu,e=b?buildPlan([it],docsOf,S)[0]:null,cells=(e?.cells||[]).filter(c=>c.status!=='skip');return`<section class="panel"><div class="panel-heading"><h2>飞书记录</h2><span class="tag ${!b?'gray':e?.error?'red':'dark'}">${!b?'未关联':e?.error?'关联失效':'已关联'}</span></div><div class="stage-body">${b?e?.error?`<p class="error" style="margin:0 0 10px">${esc(e.error)}</p>`:`<div class="file-chip">${esc(e.sheet.name)} · ${esc(cellOf(e.sheet.rows[e.row],e.sheet.map,'author'))}${e.sheet.map.platform>=0?' · '+esc(cellOf(e.sheet.rows[e.row],e.sheet.map,'platform')):''}${fsTypeOf(e.sheet,e.row)?' · '+esc(fsTypeOf(e.sheet,e.row)):''}</div><details class="fb-raw-log fs-row-log"><summary>精炼表这一行的全部信息</summary>${e.sheet.headers.map((h,i)=>h?`<div><span class="muted">${esc(h)}</span>　${esc(e.sheet.rows[e.row][i]||'（空）')}</div>`:'').join('')}</details>${cells.length?`<div class="fs-mini">${cells.map(c=>`<div><span>${esc(c.header)}</span><span>${esc(c.feishu||'（空）')} → ${esc(c.ours||'（空）')}</span><span class="tag ${fsTone(c.status)}">${fsWord(c.status)}</span></div>`).join('')}</div>`:''}`:`<p class="muted" style="margin:0">${S.length?'还没有和精炼表的某一行关联。':'先到“飞书同步”页粘贴已读取的子表，再回来关联。'}</p>`}<p class="muted" style="margin:10px 0">在飞书同步页查看并更新进度。</p><div class="toolbar-actions">${e&&!e.error&&fsFillable(it,e).length?btn('fs-fill','用飞书行补全任务信息','small primary',`data-id="${esc(it.id)}"`):''}${S.length?btn('fs-bind',b?'重新关联':'关联飞书行','small',`data-id="${esc(it.id)}"`):''}${btn('go-feishu','飞书同步页 →','small',`data-pid="${esc(p.id)}"`)}</div></div></section>`;}
function fsPreview(d){const rows=d.rows.slice(0,3),fs=FIELDS.filter(f=>d.map[f.k]>=0);if(!fs.length)return'<p class="muted">还没有对应任何字段。</p>';return`<table class="task-table"><thead><tr>${fs.map(f=>`<th>${esc(f.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${fs.map(f=>`<td><div class="fs-val">${esc(cellOf(r,d.map,f.k))}</div></td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function fsMapModal(){const d=fsDraft,opts=sel=>`<option value="-1">（没有这一列）</option>`+d.headers.map((h,i)=>`<option value="${i}" ${i===sel?'selected':''}>${esc(h||`第 ${i+1} 列`)}</option>`).join(''),fields=d.mode==='raw'?FIELDS.filter(f=>['author','platform','kind','title','date','script'].includes(f.k)):FIELDS;modal('确认字段对应',`<p>工作台已按表头自动对应，请检查。${d.mode==='raw'?'“脚本”列用来判断图文：脚本写“/”的行按图文处理。':'请选择对应列。'}</p><div class="file-chip">${d.rows.length} 行数据 · ${d.headers.filter(Boolean).length} 列表头</div><div class="form-grid" style="margin-top:14px">${fields.map(f=>`<div class="field"><label for="fm-${f.k}">${esc(f.label)}${f.need?'（必选）':''}</label><select id="fm-${f.k}" class="input" data-fm="${f.k}">${opts(d.map[f.k])}</select></div>`).join('')}</div><p class="muted" style="margin:14px 0 6px">前 3 行预览</p><div class="fs-preview">${fsPreview(d)}</div>`,btn('close-modal','取消')+btn('fs-map-confirm',d.mode==='raw'?'下一步：选择要建的任务':'保存快照','primary'));}
// 执行提炼在本机持久化，AI 只送草稿；确认建任务、空表写入只在用户点击事件中执行。
async function storeExtraction(d){await persistAI([['integrations',d]]);const i=extractions.findIndex(x=>x.id===d.id);if(i<0)extractions.unshift(d);else extractions[i]=d;}
async function saveExtraction(projectId,data){
 if(!settings.projects.some(p=>p.id===projectId&&p.status!=='ended'))throw Error('原项目已移除或结束，提炼未保存。');
 const sourceSignature=JSON.stringify({url:data.sourceUrl,revision:data.revision,entries:data.entries});const existing=extractions.find(d=>d.projectId===projectId&&d.sourceSignature===sourceSignature);if(existing)return existing;
 const d={id:uid(),projectId,sourceSignature,at:new Date().toISOString(),status:'draft',sourceUrl:data.sourceUrl,title:data.title,revision:data.revision,sources:data.sources,reconciliation:data.reconciliation,warnings:data.warnings||[],entries:data.entries.map(extractionDefaults)};
 await storeExtraction(d);if(page==='feishu'&&!typing())render();toast('提炼结果已保存。');return d;
}
function extractionCard(p){const ds=extractions.filter(d=>d.projectId===p.id).sort((a,b)=>b.at.localeCompare(a.at));return `<section class="panel" id="fs-extractions"><div class="panel-heading"><h2>执行提炼</h2><span class="muted">由 AI 客户端发起提炼</span></div><div class="stage-body">${ds.length?ds.map(d=>`<div class="ai-row"><div class="ai-row-head"><span><strong>${esc(d.title||'执行表')}</strong> · ${date(d.at)} · ${d.entries.length} 条 <span class="tag ${d.status==='draft'?'amber':'dark'}">${d.document?.verified?'飞书文档已生成':d.status==='draft'?'待核对':'已建任务'}</span></span><div class="toolbar-actions">${btn('extract-open',d.status==='draft'&&!d.document?.verified?'核对与编辑':'查看提炼结果','small',`data-id="${esc(d.id)}"`)}${d.document?.url?`<a class="button small" href="${esc(d.document.url)}" target="_blank" rel="noopener noreferrer">打开生成的精炼表 ↗</a>`:btn('extract-publish','生成飞书精炼表','small primary',`data-id="${esc(d.id)}"`)}${d.status!=='draft'?btn('extract-seed','填入空白精炼表','small primary',`data-id="${esc(d.id)}"`):''}</div></div><p class="muted">${(d.sources||[]).map(s=>`${esc(s.name)}${s.hidden?'（隐藏子表）':''} ${s.rows} 条`).join('；')}</p>${(d.warnings||[]).map(w=>`<p class="callout">${esc(w)}</p>`).join('')}${d.seedResults?.length?`<p class="muted">最近填充：${d.seedResults.map(r=>`${esc(r.name)}：${r.ok?'已填入 '+r.rows+' 行':esc(r.error)}`).join('；')}</p>`:''}</div>`).join(''):'<p class="muted">保存原始表链接后，在 AI 客户端说“用知稿提炼”。</p>'}</div></section>`;}
let extractionEdit=null,seedPlan=null;
function extractionModal(d){extractionEdit=structuredClone(d);const draft=d.status==='draft'&&!d.document?.verified;modal('核对执行提炼',`<p>项目：${esc(pnameById(d.projectId))}。查看或补充执行记录。</p>${draft&&d.entries.some(e=>!e.product)?`<div class="callout">合作产品可留空；有明确来源时再补充。<div class="toolbar-actions" style="margin-top:8px"><input class="input" id="extract-default-product" placeholder="给空白产品格填入共同产品名称">${btn('extract-fill-product','只填空白产品格','small')}</div></div>`:''}<div class="fs-list"><table class="task-table"><thead><tr><th>选择</th>${EXEC_FIELDS.map(k=>`<th>${EXEC_LABELS[k]}</th>`).join('')}</tr></thead><tbody>${d.entries.map((e,i)=>`<tr><td><input type="checkbox" data-ex-row="${i}" ${e.on?'checked':''} ${draft?'':'disabled'} aria-label="选择执行记录 ${i+1}"></td>${EXEC_FIELDS.map(k=>`<td>${k==='kind'||k==='platform'?`<select class="input" data-ex-index="${i}" data-ex-field="${k}" ${draft?'':'disabled'}>${['',...(k==='kind'?['视频','图文']:PLATFORMS)].map(v=>`<option value="${esc(v)}" ${e[k]===v?'selected':''}>${esc(v||'请选择')}</option>`).join('')}</select>`:`<input class="input" style="min-width:110px" data-ex-index="${i}" data-ex-field="${k}" value="${esc(e[k]||'')}" ${draft?'':'readonly'} aria-label="记录 ${i+1} ${EXEC_LABELS[k]}">`}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">可按来源分组查看，补充内容负责人和缺失信息。</p>`,btn('close-modal','关闭')+(draft?btn('extract-save','保存草稿')+btn('extract-confirm','确认并新建任务','primary'):''));}
function readExtractionForm(){if(!extractionEdit)throw Error('提炼草稿已失效。');for(const el of document.querySelectorAll('[data-ex-field]'))extractionEdit.entries[Number(el.dataset.exIndex)][el.dataset.exField]=el.value.trim();for(const el of document.querySelectorAll('[data-ex-row]'))extractionEdit.entries[Number(el.dataset.exRow)].on=el.checked;return extractionEdit;}
async function confirmExtraction(){const d=readExtractionForm(),p=project();if(d.projectId!==p.id||p.status==='ended')throw Error('项目已变化，请重新打开提炼草稿。');if(extractions.find(x=>x.id===d.id)?.status!=='draft')throw Error('这份提炼已经确认过。');const entries=validateExecutionRows(d.entries.filter(e=>e.on)),mine=new Set(items.filter(i=>i.projectId===p.id).map(i=>executionKey({author:i.author,platform:i.platform,product:i.title}))),made=[];
 for(const e of entries){const key=executionKey(e);if(mine.has(key))continue;mine.add(key);const fields=executionTask(e),it=makeItem({projectId:p.id,...fields});it.execution={owner:e.owner,direction:e.direction,group:e.group,source:e.source};if(fields.date)it.publish={date:fields.date,link:'',status:'已排期'};made.push(it);}
 const updated={...d,status:'confirmed',confirmedAt:new Date().toISOString(),confirmedEntries:entries,taskIds:made.map(i=>i.id)};
 await persistAI([['integrations',updated],...made.map(i=>['items',i])]);items.unshift(...made);extractions[extractions.findIndex(x=>x.id===d.id)]=updated;extractionEdit=null;closeModal();render();toast(`已新建 ${made.length} 个任务，跳过 ${entries.length-made.length} 个已有任务。`);
}
async function prepareSeed(d){const p=project(),url=fsOf(p).refined?.url;if(d.projectId!==p.id||d.status!=='confirmed'||!url)throw Error('请先确认提炼并保存本项目专门准备的空白精炼表链接。');
 const data=await feishuLocal('readAll',{url});if(p.id!==project().id||fsOf(p).refined?.url!==url)throw Error('项目或精炼表链接已变化，请重试。');await fsReadAllIntoProject(p,data);
 const groups=[...new Set(d.confirmedEntries.map(e=>e.group))];seedPlan={id:d.id,pid:p.id,url,sheets:data.sheets,groups};
 modal('选择空白精炼子表',`<p>选择要填入的空白精炼子表。</p>${groups.map((g,i)=>`<div class="field" style="margin-top:12px"><label>${esc(g)} · ${d.confirmedEntries.filter(e=>e.group===g).length} 条</label><select class="input" data-seed-group="${i}"><option value="">本次不填</option>${data.sheets.map(s=>`<option value="${esc(s.sheetId)}" ${s.name===g?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div>`).join('')}<label style="display:block;margin-top:16px"><input type="checkbox" id="seed-empty-confirm"> 我确认这是为这些执行记录准备的空白精炼表</label>`,btn('close-modal','取消')+btn('extract-seed-preview','核对写入内容','primary'));
}
function previewSeed(){const p=seedPlan,d=p&&extractions.find(d=>d.id===p.id);if(!p||!d||p.pid!==project().id||p.url!==fsOf(project()).refined?.url)throw Error('填充计划已失效。');if(!$('#seed-empty-confirm')?.checked)throw Error('请先确认空白精炼表用途。');const selected=new Set(),writes=[];
 for(const el of document.querySelectorAll('[data-seed-group]')){if(!el.value)continue;if(selected.has(el.value))throw Error('一个子表不能接收多个分组，请分别准备空白子表。');selected.add(el.value);const sheet=p.sheets.find(s=>s.sheetId===el.value),group=p.groups[Number(el.dataset.seedGroup)],entries=d.confirmedEntries.filter(e=>e.group===group);if(sheet.rows.some(r=>r.some(v=>String(v).trim())))throw Error(`「${sheet.name}」已有数据，不能用于空表填充。`);if(entries.length>100)throw Error('一个子表单次最多 100 条。');const rows=seedRows(sheet.headers,entries);writes.push({sheetId:sheet.sheetId,name:sheet.name,headers:sheet.headers,entries:entries.map(e=>Object.fromEntries(EXEC_FIELDS.map(k=>[k,e[k]||'']))),rows});}
 if(!writes.length)throw Error('请选择至少一个目标子表。');p.writes=writes;
 modal('确认填入空白精炼表',`<p>目标：${esc(p.url)}。以下 ${writes.reduce((n,w)=>n+w.rows.length,0)} 条记录经你确认后填入既有空白行。</p>${writes.map(w=>`<h3>${esc(w.name)}</h3><div class="fs-list"><table class="task-table"><thead><tr>${w.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${w.rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`).join('')}`,btn('close-modal','取消')+btn('extract-seed-confirm','填入精炼表','primary'));
}
async function executeSeed(button){const plan=seedPlan;seedPlan=null;if(!plan?.writes||plan.pid!==project().id||plan.url!==fsOf(project()).refined?.url)throw Error('填充计划已失效，请重新核对。');button.disabled=true;closeModal();const d=structuredClone(extractions.find(d=>d.id===plan.id)),results=[];
 for(const w of plan.writes){try{const result=await feishuLocal('seed',{url:plan.url,sheetId:w.sheetId,headers:w.headers,entries:w.entries,confirmEmptyTarget:true});results.push({name:w.name,ok:true,rows:result.writtenRows});}catch(e){results.push({name:w.name,ok:false,error:e.message});}}
 d.seedResults=results;d.seedAt=new Date().toISOString();await storeExtraction(d);const p=settings.projects.find(p=>p.id===plan.pid);if(p&&fsOf(p).refined?.url===plan.url)try{await fsReadAllIntoProject(p,await feishuLocal('readAll',{url:plan.url}));await bindExactLive(p);}catch(e){toast('填充结束，但刷新失败：'+e.message);}
 render();toast(`空表填充：${results.filter(r=>r.ok).length} 个子表已填入，${results.filter(r=>!r.ok).length} 个未完成。请查看提炼记录。`);
}
async function bindExactLive(p){const sheets=fsLiveSheets(p),used=new Set(items.filter(i=>i.projectId===p.id&&i.feishu).map(i=>`${i.feishu.sheetId}|${i.feishu.key}`));let count=0;
 for(const it of items.filter(i=>i.projectId===p.id&&!i.feishu)){const hits=exactCreatorRows(it,sheets);if(hits.length!==1)continue;const {s,row}=hits[0],key=rowKey(s,row),id=`${s.id}|${key}`;if(used.has(id))continue;const updated={...it,feishu:{sheetId:s.id,key}};await persistAI([['items',updated]]);Object.assign(it,updated);used.add(id);count++;}return count;
}
async function prepareFeishuSync(){const p=project(),url=fsOf(p).refined?.url;if(p.status==='ended'||!url)throw Error('请选择执行中的项目并保存精炼表链接。');const data=await feishuLocal('readAll',{url});if(fsOf(p).refined?.url!==url)throw Error('精炼表链接已变化，未更新核对计划。');await fsReadAllIntoProject(p,data);const linked=await bindExactLive(p),writes=fsLiveWrites(p);if(settings.selected===p.id&&!typing()){page='feishu';render();}return {ok:true,project:p.name,linked,unmatched:items.filter(i=>i.projectId===p.id&&!i.feishu).map(i=>({author:i.author,platform:i.platform,reason:exactCreatorRows(i,fsLiveSheets(p)).length>1?'昵称匹配到多行，请选择':'未找到唯一昵称匹配'})),awaitingConfirmation:writes.length,written:0,location:'工作台 → 飞书同步 → 同步进度',message:writes.length?'已准备差异，等待用户在网页确认。':'当前没有可写入差异。AI 审稿不等于品牌通过，✅ 仅来自人工记录。'};}

function fsBuildEntries(){const d=fsDraft,p=project(),key=(a,pl,t)=>`${normName(a)}|${pl}|${normName(t)}`,mine=new Set(items.filter(i=>i.projectId===p.id).map(i=>key(i.author,i.platform,i.title))),seen=new Set(),out=[];for(const r of d.rows){const author=cellOf(r,d.map,'author');if(!author)continue;const ps=platformsOf(cellOf(r,d.map,'platform')),kind=kindOf(cellOf(r,d.map,'kind'))||(cellOf(r,d.map,'script')==='/'?'图文':'')||d.defKind,title=cellOf(r,d.map,'title'),type=cellOf(r,d.map,'type'),rawDate=cellOf(r,d.map,'date'),date=dateISO(rawDate);for(const platform of ps.length?ps:[d.defPlat]){const k=key(author,platform,title),st=mine.has(k)?'exists':seen.has(k)?'dup':'new';seen.add(k);out.push({author,platform,kind,type,title,date,rawDate,guessPlat:!ps.length,st,on:st==='new'});}}d.entries=out;}
function fsExtractList(){const d=fsDraft,E=d.entries;if(!E.length)return'<p class="error">没有读到带达人名的行，请检查“达人”对应的列。</p>';return`<table class="task-table"><thead><tr><th style="width:36px"></th><th>达人</th><th>平台</th><th>形式</th><th>标题 / 产品</th><th>档期</th><th>说明</th></tr></thead><tbody>${E.map((e,i)=>`<tr><td><input type="checkbox" data-fx="${i}" aria-label="导入第 ${i+1} 条" ${e.on?'checked':''}></td><td>${esc(e.author)}${e.type?`<small class="muted" style="display:block">${esc(e.type)}</small>`:''}</td><td>${esc(e.platform)}${e.guessPlat?' <span class="tag gray">默认</span>':''}</td><td>${esc(e.kind)}</td><td>${esc(e.title||'—')}</td><td>${esc(e.date||e.rawDate||'—')}</td><td>${e.st==='exists'?'<span class="tag gray">已有任务，默认跳过</span>':e.st==='dup'?'<span class="tag amber">与上面重复，默认跳过</span>':'将新建'}</td></tr>`).join('')}</tbody></table>`;}
function fsExtractModal(){fsBuildEntries();const d=fsDraft;if(d.entries.length>300)throw Error(`一次最多处理 300 条，这次有 ${d.entries.length} 条，请分批粘贴。`);modal('选择要新建的内容任务',`<p>一个达人在一个平台的一篇内容是一个任务；一行写了多个平台会拆开。勾选要新建的任务，项目是「${esc(pname(project()))}」。</p><div class="form-grid"><div class="field"><label for="fx-kind">内容形式没写时按</label><select id="fx-kind" class="input">${['视频','图文'].map(x=>`<option ${x===d.defKind?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="fx-plat">平台没写时按</label><select id="fx-plat" class="input">${PLATFORMS.map(x=>`<option ${x===d.defPlat?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="fs-list" id="fx-list" style="margin-top:14px">${fsExtractList()}</div>`,btn('close-modal','取消')+btn('fs-extract-confirm','新建勾选的任务','primary'));}
function fsRefinedRows(list){const s=fsOf(project()).sheets[0],val=(it,f)=>({author:it.author,platform:it.platform,kind:it.kind,type:it.type||'',title:it.title,date:it.publish?.date||'',script:it.kind==='图文'?'/':''})[f]??'';if(s)return list.map(it=>s.headers.map((_,i)=>{const f=Object.keys(s.map).find(k=>s.map[k]===i);return f?val(it,f):'';}));const H=[['达人','author'],['发布平台','platform'],['内容形式','kind'],['内容标题','title'],['发布档期','date'],['大纲','outline'],['脚本','script'],['初稿','draft'],['发布情况','publish'],['品牌方反馈','feedback'],['达人类型','type']];return[H.map(h=>h[0]),...list.map(it=>H.map(h=>val(it,h[1])))];}
async function copyText(text,label){try{await navigator.clipboard.writeText(text);toast(`已复制${label}，可以到飞书里粘贴。`);}catch{modal(`复制${label}`,`<p>浏览器没有允许自动复制，请按 Ctrl+C 复制下面已选中的内容。</p><textarea id="copy-box" readonly>${esc(text)}</textarea>`,btn('close-modal','完成','primary'));setTimeout(()=>$('#copy-box')?.select(),50);}}
function fsPlanText(p){const S=fsLiveSheets(p),plan=buildPlan(items.filter(i=>i.projectId===p.id&&i.feishu),docsOf,S),now=new Date().toLocaleString('zh-CN'),out=[`飞书待更新清单（在线数据核对于 ${now}）`,''],todo=plan.filter(e=>e.cells?.some(c=>c.status==='update')),hard=plan.filter(e=>e.error||e.cells?.some(c=>c.status==='conflict'));if(todo.length){out.push('一、待人工确认后可写入的空格');for(const e of todo){out.push(`【${e.sheet.name}】${itemName(e.it)}（${e.it.platform}）`);for(const c of e.cells.filter(c=>c.status==='update'))out.push(`  ${c.header}：${c.ours}`);}out.push('');}if(hard.length){out.push('二、待处理差异');for(const e of hard){out.push(`【${e.sheet?.name||'—'}】${itemName(e.it)}（${e.it.platform}）`);if(e.error)out.push(`  ${e.error}`);for(const c of (e.cells||[]).filter(c=>c.status==='conflict'))out.push(`  ${c.header}：飞书“${c.feishu}”，工作台“${c.ours||'（空）'}”（${c.note}）`);}}return out.join(String.fromCharCode(10)).trim();}
function fsBindModal(it){const p=settings.projects.find(x=>x.id===it.projectId)||project(),S=fsLiveSheets(p).length?fsLiveSheets(p):fsOf(p).sheets,c=candidates(it,S),taken=k=>items.find(i=>i!==it&&i.feishu&&i.feishu.key===k);modal(`关联飞书行：${itemName(it)}`,`<p>按达人名和平台找到候选行；标题用于区分同一达人同平台的多篇内容。若“达人＋平台＋标题”仍重复，须人工选择正确行。</p>${c.length?c.map((x,k)=>{const s=S.find(y=>y.id===x.sheetId),key=rowKey(s,x.row),o=taken(key);return`<label class="fs-cand"><input type="radio" name="fs-cand" value="${esc(x.sheetId)}|${x.row}" ${k===0?'checked':''}><span><strong>${esc(x.author)}</strong> · ${esc(x.platform||'平台未写')} · ${esc(x.title||'无标题')}<small class="muted" style="display:block">子表：${esc(x.sheet)}${o?` · 已关联到：${esc(itemName(o))}（${esc(o.platform)}）`:''}</small></span></label>`;}).join(''):`<div class="callout">在线表格里没有找到「${esc(it.author)}」在${esc(it.platform)}的候选行。请核对表格后重新读取。</div>`}`,btn('close-modal','取消')+(it.feishu?btn('fs-unbind','解除关联','',`data-id="${esc(it.id)}"`):'')+(c.length?btn('fs-bind-confirm','关联','primary',`data-id="${esc(it.id)}"`):''));}
