function fsPasteModal(mode,sid){const p=project(),s=sid?fsOf(p).sheets.find(x=>x.id===sid):null;modal(mode==='raw'?'粘贴原始资料表':s?`更新数据：${s.name}`:'粘贴精炼表子表',`<p>在飞书里选中整张子表（包含表头那一行），按 Ctrl+C 复制，再粘贴到下面。</p>${mode==='sheet'?`<label class="muted" for="fs-name">子表名称</label><input id="fs-name" class="input" value="${esc(s?.name||'')}" placeholder="例如：家国情怀@诗晴" style="margin:6px 0 12px">`:''}<label class="muted" for="fs-text">表格内容</label><textarea id="fs-text" placeholder="在这里粘贴（Ctrl+V）"></textarea>`,btn('close-modal','取消')+btn('fs-paste-next','下一步','primary',`data-mode="${mode}"${s?` data-sid="${esc(s.id)}"`:''}`));}
function itemPage(){const it=item,pr=itemProgress(it,docsOf(it));return`<div class="review-top"><div class="review-title"><button class="textbtn back" data-page="history">← 内容任务</button><div class="eyebrow" style="margin-bottom:8px">TASK / ${esc(pnameById(it.projectId))}</div><h1>${esc(itemName(it))}</h1><p>${esc(it.platform)} · ${esc(it.kind)}${it.type?' · '+esc(it.type):''} · 创建于 ${date(it.created)}${it.migrated?' · 由旧稿件自动生成':''}</p></div><div class="toolbar-actions">${btn('bundle-export-item',icon('down')+' 导出交接包')}${btn('edit-item',icon('edit')+' 编辑任务信息')}${btn('delete-item',icon('trash')+' 删除任务')}</div></div><section class="progress-panel"><div class="flow-head"><div><div class="eyebrow">PROGRESS</div><h3>当前：${esc(pr.current)} <span class="tag ${pr.tone}">${esc(pr.label)}</span></h3></div>${steps(pr,it,true)}</div>${it.kind==='图文'?'<p class="flow-hint">图文没有脚本阶段。</p>':''}</section><div class="item-grid"><div>${pr.stages.map(s=>stageCard(it,s,pr)).join('')}</div><aside>${publishCard(it,pr)}${folderCard(settings.projects.find(p=>p.id===it.projectId)||project())}${feishuCard(it)}</aside></div>`;}
