const WAIT_ORDER=['me','brand','creator','publish'],WAIT_HINT={me:'审稿、复核或交品牌',brand:'已交品牌，等回复',creator:'等达人交稿或改稿',publish:'内容已通过，盯发布'};
function todoRow(it,pr){const n=daysToPublish(it),fb=openFeedback(docsOf(it)),pend=pr.doc?reviewStatus(pr.doc):null;return`<button class="todo-row" data-action="open-item" data-id="${esc(it.id)}"><span class="todo-main"><strong>${esc(itemName(it))}</strong><small>${esc(it.platform)} · ${esc(it.kind)}${it.type?' · '+esc(it.type):''} · ${esc(pr.current)} · ${esc(pr.label)}</small></span><span class="todo-meta">${n!=null?`<span class="tag ${n<0?'red':n<=3?'amber':'gray'}">${esc(dueLabel(n))}</span>`:''}${fb?`<span class="tag red">${fb} 条反馈待处理</span>`:''}${pend?.tone?`<span class="tag amber">${esc(pend.label)}</span>`:''}</span></button>`;}
function todoBoard(list){const rows=list.map(it=>{const pr=itemProgress(it,docsOf(it));return{it,pr,w:waitingOn(it,pr),n:daysToPublish(it)};}).filter(r=>r.w!=='done'),by=(a,b)=>(a.n??1e9)-(b.n??1e9)||String(b.it.updated).localeCompare(String(a.it.updated)),urgent=rows.filter(r=>r.n!=null&&r.n<=3).sort(by);if(!rows.length)return`<div class="empty">${icon('check')}<p>${list.length?'这个品牌的任务都已发布':'还没有内容任务'}</p><small>${list.length?'有新的达人内容时，新建内容任务或直接上传来稿。':'新建一个“达人＋平台＋一篇内容”的任务，或直接上传来稿。'}</small></div>`;return`${urgent.length?`<section class="todo-group urgent"><div class="todo-head"><h3>${icon('alert')} 档期临近</h3><span class="muted">3 天内发布或已过档期 · ${urgent.length} 个</span></div>${urgent.map(r=>todoRow(r.it,r.pr)).join('')}</section>`:''}<div class="todo-grid">${WAIT_ORDER.map(w=>{const g=rows.filter(r=>r.w===w).sort(by);return`<section class="todo-group"><div class="todo-head"><h3>${WAIT[w]} <span class="count-pill">${g.length}</span></h3><span class="muted">${WAIT_HINT[w]}</span></div>${g.length?g.slice(0,6).map(r=>todoRow(r.it,r.pr)).join('')+(g.length>6?`<button class="textbtn todo-more" data-action="todo-more" data-w="${w}">还有 ${g.length-6} 个 → 在列表里查看</button>`:''):'<p class="todo-empty">暂无</p>'}</section>`;}).join('')}</div>`;}
function home(){const p=project(),list=items.filter(i=>i.projectId===p.id),prs=list.map(it=>({it,pr:itemProgress(it,docsOf(it))})),n=w=>prs.filter(x=>waitingOn(x.it,x.pr)===w).length;return`<div class="page-title"><div><div class="eyebrow" style="margin-bottom:10px">A LITTLE LESS REWRITING. A LITTLE MORE RIGHT.</div><h1>每一处修改，都有依据。</h1><p>保留创作者的表达，把必要的地方改对。</p></div><div class="toolbar-actions">${btn('new-item',icon('plus')+' 新建内容任务')}${btn('upload',icon('upload')+' 上传稿件','primary')}</div></div><div class="stats">${[['me','待我处理','edit'],['brand','等品牌反馈','history'],['creator','等达人稿件','arrow'],['publish','待发布','doc']].map(([w,t,i])=>`<button class="stat" data-action="todo-more" data-w="${w}"><label>${t}${icon(i)}</label><div class="stat-number">${n(w)}<span>个</span></div></button>`).join('')}</div><div class="section-title"><h2>今天要盯的 · ${esc(pname(p))}</h2><button class="textbtn" data-page="history">全部任务 →</button></div><div class="todo-wrap">${todoBoard(list)}</div>${batchBoard(p)}<div id="ai-results">${aiBoard(p)}</div><div class="start-grid"><section class="panel"><div class="panel-heading"><h2>上传一份来稿</h2><small>01 / IMPORT</small></div><div class="upload-body"><div class="dropzone" id="dropzone" role="button" tabindex="0" aria-label="上传稿件"><div class="upload-icon">${icon('upload')}</div><b>拖入来稿，或 <span>点击上传</span></b><small>支持 Excel .xlsx、Word .docx、PDF、纯文本 .txt / .md · 视频 .mp4 / .mov / .webm · 文档最大 15 MB，视频最大 2 GB（PDF、视频只读，按页或时间点写意见）</small></div><div class="upload-meta"><span>上传后选择所属内容任务和阶段</span><div class="upload-actions"><button class="textbtn" data-action="paste">粘贴文案</button><button class="textbtn" data-action="demo">打开示例 ${icon('arrow')}</button></div></div></div></section><section class="panel"><div class="panel-heading"><h2>当前品牌项目</h2><small>02 / PROJECT</small></div><div class="project-info"><select class="project-select" data-setting="project" aria-label="当前项目">${projectOptions()}</select>${p.status==='ended'?`<div class="callout">该项目已结束${p.sample?'，仅作历史示例':''}。新品牌请新建项目。<br><button class="textbtn" data-action="new-project" style="padding:4px 0 0">新建品牌项目 →</button></div>`:''}<ul class="principles"><li>${icon('check')}最小必要修改，尽量沿用原稿</li><li>${icon('check')}只把新增、替换的字标红</li><li>${icon('check')}修改理由只留在工作台</li><li>${icon('check')}导出修改稿</li></ul><div class="project-foot"><span>口径更新 · ${esc(project().date)}</span><button class="textbtn" data-page="brand">品牌资料 →</button></div></div></section></div>`;}
// 一处 AI 修改的摘要：只截取前后变化附近的文字。
function aiSnippet(a,b){a=String(a||'');b=String(b||'');let i=0;while(i<a.length&&i<b.length&&a[i]===b[i])i++;let j=0;while(j<a.length-i&&j<b.length-i&&a[a.length-1-j]===b[b.length-1-j])j++;const cut=(s,x,y)=>{const m=s.slice(x,s.length-y);return m.length>24?m.slice(0,24)+'…':m;};return{from:cut(a,i,j)||'（无）',to:cut(b,i,j)||'（删除）'};}
function batchBoard(p){const list=batches.filter(b=>b.projectId===p.id).sort((a,b)=>b.created.localeCompare(a.created));return `<div id="review-batches">${list.length?`<section class="panel ai-board-batches"><div class="panel-heading"><h2>${icon('spark')} AI 审稿批次</h2><span class="muted">结果待人工确认</span></div>${list.slice(0,5).map(b=>{const s=batchSummary(b);return `<div class="ai-row"><div class="ai-row-head"><strong>${date(b.created)} · ${b.entries.length} 份</strong><span class="muted">完成 ${s.success} · 失败 ${s.failed} · 中断 ${s.interrupted} · 跳过 ${s.skipped}</span></div><div class="muted" style="font-size:12px;overflow-wrap:anywhere">批次 ${esc(b.id)} · 排队 ${s.counts.queued} · 审稿中 ${s.counts.reviewing}</div>${b.entries.map(e=>`<div class="ai-row-head" style="margin-top:10px"><span>${esc(e.author||'未填写达人')} · ${esc(e.stage)} · 第 ${e.round} 轮 <span class="tag ${e.status==='failed'?'red':e.status==='pending'?'amber':'gray'}">${BATCH_STATES[e.status]||esc(e.status)}</span>${e.reason?`<small class="muted"> ${esc(e.reason)}</small>`:''}</span>${btn(e.status==='pending'?'open-ai':'open-task',e.status==='pending'?'查看改前改后':'打开稿件','small',`data-id="${esc(e.docId)}"`)}</div>`).join('')}</div>`;}).join('')}</section>`:''}</div>`;}
function aiBoard(p){const docs=tasks.filter(t=>t.projectId===p.id&&(t.ai?.changes?.length||t.ai?.warnings?.length)).sort((a,b)=>String(b.ai.at||b.updated).localeCompare(String(a.ai.at||a.updated)));if(!docs.length)return'';return`<section class="panel ai-board"><div class="panel-heading"><h2>${icon('spark')} AI 审稿结果</h2><span class="muted" style="font-size:12px">${docs.length} 份稿件 · 每处修改都待你确认</span></div>${docs.slice(0,8).map(t=>{const it=itemOf(t),ch=t.ai.changes||[],pn=ch.filter(x=>x.status==='pending').length,ok=ch.filter(x=>x.status==='accepted').length,ws=t.ai.warnings||[];return`<div class="ai-row"><div class="ai-row-head"><div><strong>${esc(t.author||'未填写达人')}</strong> <span class="muted">${esc(t.platform||'')}${it?.type?' · '+esc(it.type):''} · ${esc(t.stage)} · 第 ${flowOf(t).round} 轮${t.ai.at?' · '+date(t.ai.at):''}</span></div><div class="ai-row-tags">${pn?`<span class="tag amber">${pn} 处待确认</span>`:''}${ok?`<span class="tag dark">已采纳 ${ok}</span>`:''}${ws.length?`<span class="tag gray">提醒 ${ws.length}</span>`:''}${btn('open-ai','查看改前改后','small',`data-id="${esc(t.id)}"`)}</div></div>${ch.length?`<ul class="ai-changes">${ch.slice(0,3).map(x=>{const s=aiSnippet(x.original,x.revised);return`<li><span class="ai-from">${esc(s.from)}</span> → <span class="ai-to">${esc(s.to)}</span>${x.reason?` <span class="muted">· ${esc(String(x.reason).slice(0,40))}</span>`:''}</li>`;}).join('')}${ch.length>3?`<li class="muted">还有 ${ch.length-3} 处…</li>`:''}</ul>`:''}</div>`;}).join('')}${docs.length>8?`<p class="muted" style="padding:10px 24px;margin:0;font-size:12px">只显示最近 8 份，其余在内容任务里打开。</p>`:''}</section>`;}
function historyPage(){const list=listItems();return`<div class="page-title"><div><h1>内容任务</h1><p>一个任务就是一个达人在一个平台的一篇内容；阶段、轮次和发布都记在任务里。</p></div><div class="toolbar-actions">${btn('new-item',icon('plus')+' 新建内容任务')}${btn('upload',icon('upload')+' 上传稿件','primary')}</div></div><div class="data-actions" style="margin:-12px 0 18px">${btn('bundle-export',icon('down')+' 导出交接 / 备份包','small')}${btn('bundle-import',icon('upload')+' 导入交接包','small')}${btn('legacy-help',icon('history')+' 迁移原站旧数据','small')}</div><div class="section-title"><div class="list-filters"><select id="list-project" class="input" aria-label="项目范围"><option value="current" ${listProject==='current'?'selected':''}>当前项目：${esc(pname(project()))}</option><option value="all" ${listProject==='all'?'selected':''}>全部项目</option></select><span class="muted" id="list-count">共 ${list.length} 个</span></div><input class="search" id="history-search" aria-label="搜索内容任务" placeholder="搜索达人、标题或平台…" value="${esc(search)}"></div>${filterBar()}<section class="panel" id="history-table">${itemTable(list)}</section>`;}
function rulesPage(){const p=project(),L=libOf(p),live=effectiveRules(p),ids=new Set(live.map(r=>r.id));return `<div class="page-title"><div><h1>品牌资料与口径</h1><p>完整资料作为依据；品牌更新要求后，以最新口径审核本项目的所有稿件。</p></div>${btn('new-project',icon('plus')+' 新建品牌项目')}</div><div class="project-switcher"><select class="input" data-setting="project" aria-label="选择品牌项目">${projectOptions()}</select>${btn('toggle-project',p.status==='ended'?'重新启用项目':'标记项目已结束')}</div>${p.sample?'<div class="banner">历史示例，仅供查阅。请选择执行中的品牌项目处理新稿件。</div>':''}<div class="brand-policy-layout"><div><section class="panel"><div class="panel-heading"><h2>品牌全部资料 <span class="muted">/ ${L.length} 份</span></h2>${btn('lib-add','＋ 添加资料','small')}</div>${L.length?L.map(d=>`<div class="lib-row ${d.active===false?'dim':''}"><button class="toggle ${d.active!==false?'on':''}" role="switch" aria-checked="${d.active!==false}" aria-label="引用到 AI 指令：${esc(d.title)}" data-action="lib-toggle" data-id="${esc(d.id)}"></button><div class="rule-copy"><h3>${esc(d.title)} <span class="tag gray">${esc(d.kind)}</span></h3><p>${esc(String(d.text).slice(0,160))}${String(d.text).length>160?'…':''}</p><small class="muted">${String(d.text).length.toLocaleString()} 字${d.source?' · 来源：'+esc(d.source):''} · 更新于 ${date(d.updated)}</small></div><div class="lib-actions"><button class="textbtn" data-action="lib-edit" data-id="${esc(d.id)}">编辑</button><button class="textbtn" data-action="lib-del" data-id="${esc(d.id)}" aria-label="删除资料">${icon('trash')}</button></div></div>`).join(''):'<div class="empty">还没有资料。把品牌方给的 Brief、产品卖点、禁用词粘贴进来，AI 深审时就会按这些标准审。</div>'}</section><section class="panel" id="brand-current-rules"><div class="panel-heading"><h2>最新口径与硬性要求 <span class="muted">/ ${live.length} 条生效</span></h2>${btn('add-rule','＋ 更新口径','small primary')}</div><div class="stage-body policy-intro">本项目统一采用最新口径；与 Brief 冲突时，以这里为准。</div>${(p.rules||[]).map(r=>`<div class="rule-row ${ids.has(r.id)?'':'dim'}"><button class="toggle ${r.enabled?'on':''}" role="switch" aria-checked="${!!r.enabled}" aria-label="${esc(r.title)}" data-action="toggle-rule" data-id="${esc(r.id)}"></button><div class="rule-copy"><h3>${esc(r.title)} <span class="tag gray">${ids.has(r.id)?'生效中':r.enabled?'已被替代':'已停用'}</span></h3><p>${esc(r.description)}</p>${r.find?`<p>查找「${esc(r.find)}」${r.action==='replace'?` → 「${esc(r.replace)||'删除'}」`:' · 提醒核对'}</p>`:''}<small class="muted">${r.updated?'更新于 '+date(r.updated):'既有口径'}${r.source?' · '+esc(r.source):''}</small>${r.history?.length?`<details class="policy-history"><summary>查看 ${r.history.length} 个历史版本</summary>${r.history.map(h=>`<p>${esc(h.updated||'原版本')} · ${esc(h.title)}：${esc(h.description)}</p>`).join('')}</details>`:''}</div><button class="textbtn" data-action="edit-rule" data-id="${esc(r.id)}">编辑</button></div>`).join('')||'<div class="empty">品牌修改要求后，在这里记录原话和来源；之后每次审稿都会读取。</div>'}</section></div><aside>${folderCard(p)}<details class="panel note-box"><summary>已有项目原始笔记</summary><p>保留导入的原文作为补充资料，冲突时以最新口径为准。</p><textarea id="project-notes" aria-label="项目原始笔记">${esc(p.notes||'')}</textarea><div class="toolbar-actions">${btn('save-notes','保存笔记','small')}${btn('import-notes','导入笔记','small')}</div></details></aside></div>`;}
const reviewHead=(sub,actions)=>`<div class="review-top"><div class="review-title"><button class="textbtn back" data-action="open-item" data-id="${esc(task.itemId||'')}">← ${esc(itemOf(task)?itemName(itemOf(task)):'内容任务')}</button><div class="eyebrow" style="margin-bottom:8px">REVIEW / ${esc(pnameById(task.projectId))}</div><h1>${esc(task.filename)}</h1><p>${sub}</p></div><div class="toolbar-actions">${actions}</div></div>`;
const metaStrip=()=>`<div class="meta-strip"><div class="field wide"><label for="author">达人名称</label><input id="author" class="input" data-meta="author" value="${esc(task.author)}" placeholder="用于导出文件命名"></div><div class="field"><label for="kind">内容形式</label><select id="kind" class="input" data-meta="kind">${['视频','图文'].map(x=>`<option ${x===task.kind?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="stage">稿件阶段</label><select id="stage" class="input" data-meta="stage">${reviewStagesFor(task.kind).map(x=>`<option ${x===task.stage?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="platform">发布平台</label><select id="platform" class="input" data-meta="platform">${PLATFORMS.map(x=>`<option ${x===task.platform?'selected':''}>${x}</option>`).join('')}</select></div></div>`;
function review(){if(view==='ai'&&!task.ai?.changes?.length)view='revised';const pend=task.findings.filter(f=>f.status==='pending'),ad=view==='ai'?new Map(aiDraftCells(task.cells,task.ai).cells.map(c=>[c.id,c.current])):null,changed=task.cells.filter(c=>c.original!==c.current).length,shown=task.findings.filter(f=>filter==='all'||f.status==='pending'),s=book?.sheets.find(s=>s.id===task.scope?.sheetId);return`${reviewHead(`${task.cells.length} 段台词 · ${changed} 段已修改`,btn('rescan',icon('rules')+' 重新审校')+btn('ai',icon('spark')+' AI 深审')+btn('export',icon('down')+' 导出新文件','primary',task.cells.length?'':'disabled'))}${metaStrip()}${flowPanel()}${fbPanel()}${book?`<div class="scope"><span>${icon('shield')} 台词审稿范围</span><select id="scope-sheet" aria-label="工作表">${book.sheets.map(sh=>`<option value="${sh.id}" ${sh.id===task.scope.sheetId?'selected':''}>${esc(sh.name)}</option>`).join('')}</select><label>列 <select id="scope-column" aria-label="台词列"><option value="">请选择</option>${[...new Set(s?.cells.map(c=>c.column)||[])].map(c=>`<option ${c===task.scope.column?'selected':''}>${c}</option>`).join('')}</select></label><label>行 <input id="scope-start" aria-label="开始行" type="number" min="1" value="${task.scope.start}" style="width:65px"> — <input id="scope-end" aria-label="结束行" type="number" min="1" value="${task.scope.end}" style="width:65px"></label><span class="grow"></span><button class="textbtn" data-action="scope">应用范围</button></div>`:''}<div class="review-grid"><section class="document"><div class="doc-toolbar"><div class="segmented">${[['revised','修改稿'],['compare','前后对照'],['original','原稿'],...(task.ai?.changes?.length?[['ai','AI 改后预览']]:[])].map(([v,label])=>`<button class="${view===v?'active':''}" data-view="${v}">${label}</button>`).join('')}</div><span class="legend">仅变动字符标红</span></div>${task.cells.map(c=>`<article class="cell-block" id="cell-${c.id.replace(/[^\w-]/g,'-')}"><div class="cell-header"><strong>${esc(book?`${s?.name} · ${c.address}`:c.address)}</strong>${c.note?`<span class="tag gray">${esc(c.note)}</span>`:''}<button class="textbtn" data-action="edit-cell" data-id="${c.id}">${icon('edit')} 手动修订</button></div>${editing===c.id?`<textarea class="cell-edit" id="cell-editor" aria-label="修订台词">${esc(c.current)}</textarea><div style="display:flex;gap:8px;justify-content:flex-end;margin-top:10px">${btn('cancel-edit','取消','small')}${btn('save-cell','保存修订','primary small',`data-id="${c.id}"`)}</div>`:view==='ai'?aiCellHTML(c,ad):view==='compare'?`<div class="two-col"><div><span class="preview-label">原稿</span><div class="cell-copy before">${esc(c.original)}</div></div><div><span class="preview-label">已确认修改</span><div class="cell-copy">${markedHTML(c.original,c.current,true)}</div></div></div>`:`<div class="cell-copy">${view==='original'?esc(c.original):markedHTML(c.original,c.current)}</div>`}</article>`).join('')||'<div class="empty-scope">还没有选定台词。请在上方选择工作表、台词列和行范围，再点击“应用范围”。<br></div>'}<div class="doc-meta">${icon('shield')} ${view==='ai'?'AI 改后预览':'当前修改稿'}</div></section><aside class="findings">${basisCard()}<div class="findings-head"><h3>规则检查 <span class="tag amber">${pend.length} 待确认</span></h3><button class="textbtn" data-action="filter">${filter==='pending'?'显示全部':'仅看待确认'}</button></div>${pend.some(f=>f.severity==='fix')?`<div style="margin-bottom:12px">${btn('accept-all','采纳全部文字建议','small soft')}</div>`:''}${shown.map(f=>`<section class="finding ${f.status==='ignored'?'dim':''}"><div class="finding-title">${icon(f.severity==='fix'?'edit':'alert')}${esc(f.title)}</div>${f.cellId?`<button class="textbtn" style="padding:7px 0 0" data-action="locate" data-id="${f.cellId}">${esc(getCell(f.cellId)?.address)} ↗</button>`:''}${typeof f.replacement==='string'?`<div class="change"><span>${esc(f.original)}</span> → <span class="replacement">${esc(f.replacement)||'删除此处'}</span></div>`:''}<p>${esc(f.reason)}</p><div class="finding-source">${f.rule.startsWith('custom-')?'自定义项目规则':'项目审稿规则'} · ${esc(task.ruleDate)}</div><div class="finding-actions">${f.status==='pending'?`<button class="textbtn" data-action="finding" data-id="${f.id}" data-status="ignored">${f.severity==='fix'?'保留原文':'暂不处理'}</button>${btn('finding',f.severity==='fix'?'采纳':'已核对','small soft',`data-id="${f.id}" data-status="accepted"`)}`:`<span class="tag ${f.status==='ignored'?'gray':''}">${f.status==='accepted'?(f.severity==='fix'?'已采纳':'已核对'):'已保留 / 跳过'}</span><button class="textbtn" data-action="finding" data-id="${f.id}" data-status="pending">撤销</button>`}</div></section>`).join('')||'<div class="finding"><div class="finding-title">'+icon('check')+' 当前规则已处理完毕</div><p>当前没有待处理的规则建议。</p></div>'}${aiPanel()}<div class="history-actions" style="margin-top:18px"><button class="textbtn" data-action="delete-task">${icon('trash')} 删除本阶段稿件</button></div></aside></div>`;}
// AI 改后预览的一段：左边原稿，右边套用 AI 建议后的全文，变动字标红；标出这段建议的状态。
const AI_WORD={pending:['待确认','amber'],accepted:['已采纳','dark'],ignored:['已保留原文','gray'],stale:['原文已变化','gray']};
function aiCellHTML(c,ad){const x=task.ai.changes.find(x=>x.id===c.id),w=x&&AI_WORD[x.status],after=ad.get(c.id)??c.current;return`${w?`<div style="margin:-4px 0 10px"><span class="tag ${w[1]}">AI 建议 · ${w[0]}</span>${x.reason?`<span class="muted" style="font-size:11px;margin-left:8px">${esc(x.reason)}</span>`:''}</div>`:''}<div class="two-col"><div><span class="preview-label">原稿</span><div class="cell-copy before">${esc(c.original)}</div></div><div><span class="preview-label">AI 改后</span><div class="cell-copy">${markedHTML(c.original,after,true)}</div></div></div>`;}
// 审稿依据：这份稿件的品牌方反馈（只用于这份）+ 项目总资料（全局）。AI 深审指令按这两部分加项目规则生成。
function basisCard(){const p=settings.projects.find(x=>x.id===task.projectId)||project(),f=flowOf(task),live=fbList(task).filter(x=>x.status!=='draft'),open=live.filter(x=>x.status==='open').length,lib=libOf(p).filter(d=>d.active!==false),last=lib.map(d=>d.updated||'').sort().at(-1),rules=(p.rules||[]).filter(r=>r.enabled).length;return`<section class="basis-card"><div class="basis-head"><strong>${icon('shield')} 审稿依据</strong><button class="textbtn" data-page="brand">项目总资料 →</button></div><div class="basis-row"><span>本稿品牌反馈</span><span>${f.feedback.length?`原话 ${f.feedback.length} 次 · 要求 ${live.length} 条${open?` · <b>${open} 条待处理</b>`:''}`:'暂无'}</span></div><div class="basis-row"><span>项目总资料</span><span>${lib.length?`启用 ${lib.length} 份${last?` · 更新于 ${esc(last.slice(0,10))}`:''}`:'暂无'}</span></div><div class="basis-row"><span>项目规则</span><span>启用 ${rules} 条</span></div></section>`;}
function aiPanel(){if(!task.ai)return'';const pn=task.ai.changes.filter(x=>x.status==='pending').length;return`<div class="findings-head" style="margin-top:22px"><h3>${icon('spark')} AI 深审建议</h3>${pn?`<span class="tag amber">${pn} 待确认</span>`:''}</div><div class="ai-meta">${task.ai.at?`${date(task.ai.at)} 导入 · `:''}修改 ${task.ai.changes.length} 处 · 提醒 ${task.ai.warnings.length} 条${task.ai.saved?`<br>AI修改版（未确认）已存：${esc(task.ai.saved.path)}`:''}${task.ai.changes.length?`<div class="ai-meta-actions">${view!=='ai'?btn('ai-preview','查看 AI 改后全文','small'):''}${pn?btn('ai-draft-save','另存 AI修改版（未确认）','small'):''}</div>`:''}</div>${task.ai.changes.map((x,i)=>`<section class="finding ${x.status==='stale'?'dim':''}"><div class="finding-title">${esc(getCell(x.id)?.address)} · 语义修订</div><p>${esc(x.reason)}</p><div class="change">${markedHTML(x.original,x.revised,true)}</div>${Array.from(x.revised).length>Array.from(x.original).length*1.3?'<p class="error">修改后文字较多。</p>':''}<div class="finding-actions">${x.status==='pending'?`${btn('ai-change','保留当前','small',`data-index="${i}" data-status="ignored"`)}${btn('ai-change','采纳','small soft',`data-index="${i}" data-status="accepted"`)}`:`<span class="tag gray">${({accepted:'已采纳',ignored:'已保留',stale:'原文已变化，请重新深审'})[x.status]}</span>`}</div></section>`).join('')}${task.ai.warnings.map(w=>`<section class="finding"><div class="finding-title">${icon('alert')} AI 提醒</div><p>${esc(w)}</p></section>`).join('')}`;}
// 品牌资料库：每个项目独立。资料原文进 AI 深审指令；原话、AI 整理、人工确认三层分开。
