 'export-pdf-notes':async()=>{task.exported=new Date().toISOString();await saveTask();await archive(SUB.notes,outName(task,'html').replace(/\.html$/,'-审稿意见单.html'),new Blob([pdfNotesHtml(task)],{type:'text/html;charset=utf-8'}),{suffix:'PDF 原件未修改。'});},
 'export':exportModal,'do-export':exportFile,'export-txt':()=>{download(new Blob([task.cells.map(c=>c.current).join('\n\n')],{type:'text/plain;charset=utf-8'}),outName(task,'txt','确认版'));toast('已下载纯文本，纯文本不包含红色标记。');},
