 'new-project':()=>modal('新建品牌项目',`<p>填写品牌名称，建立项目资料库。</p><label for="new-project-name">品牌名称</label><input id="new-project-name" class="input" style="margin-top:10px" placeholder="例如：王家渡">`,btn('close-modal','取消')+btn('create-project','创建项目','primary')),
 'create-project':()=>{const name=$('#new-project-name').value.trim();if(!name)return toast('请填写品牌名称。');const p={id:uid(),name,status:'active',notes:'尽量沿用原稿，只做必要修改；不要编造产品事实。',rules:[],files:[],date:new Date().toLocaleDateString('sv')};settings.projects.push(p);settings.selected=p.id;saveSettings();closeModal();page='rules';render();},
